    await sequelize.authenticate();
    console.log('✅ Connection to database authenticated successfully.');

    console.log('\n🔍 Checking for the "users" table...');
    const [results] = await sequelize.query('SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_schema = \'public\' AND table_name = \'users\') AS table_exists;');
    const tableExists = results[0].table_exists;
