  logSection('PHASE 1: DATABASE SCHEMA VERIFICATION');

  try {
    const client = await pool.connect();
    log('✓ Database connection established', 'green');

    // Get all existing tables
    const tablesResult = await client.query(`
      SELECT table_name 
      FROM information_schema.tables 
      WHERE table_schema = 'public' 
      ORDER BY table_name;
    `);

    const existingTables = tablesResult.rows.map(row => row.table_name);
    auditResults.database.tablesChecked = existingTables.length;

    log(`\n📊 Found ${existingTables.length} tables in database`, 'blue');

    // Check for critical tables that should exist
    const criticalTables = [
      'users', 'profiles', 'sessions', 'roles', 'permissions',
      'messages', 'conversations', 'notifications',
      'products', 'orders', 'payments', 'wallets',
      'posts', 'comments', 'likes', 'followers',
      'analytics_events', 'audit_logs'
    ];

    const missingTables = criticalTables.filter(table => !existingTables.includes(table));

    if (missingTables.length > 0) {
      log(`\n⚠️  Missing critical tables: ${missingTables.join(', ')}`, 'yellow');
      auditResults.database.tablesMissing = missingTables;

      // Attempt to fix by running migrations
      log('\n🔧 Attempting to fix missing tables via migration...', 'blue');
      try {
        const migrationScript = path.join(__dirname, 'database', 'run_master_migration.js');
        if (fs.existsSync(migrationScript)) {
          execSync(`node "${migrationScript}"`, { stdio: 'inherit' });
          log('✓ Migration executed successfully', 'green');

          // Re-check tables
          const recheck = await client.query(`
            SELECT table_name 
            FROM information_schema.tables 
            WHERE table_schema = 'public';
          `);
          const updatedTables = recheck.rows.map(row => row.table_name);
          const stillMissing = missingTables.filter(t => !updatedTables.includes(t));

          if (stillMissing.length === 0) {
            log('✓ All critical tables now exist', 'green');
            auditResults.database.tablesFixed = missingTables;
          } else {
            log(`⚠️  Still missing: ${stillMissing.join(', ')}`, 'yellow');
          }
        }
      } catch (error) {
        log(`✗ Migration failed: ${error.message}`, 'red');
      }
    } else {
      log('✓ All critical tables present', 'green');
    }

    // Check table integrity (row counts)
    log('\n📈 Table Statistics:', 'blue');
    for (const table of existingTables.slice(0, 20)) { // Check first 20 tables
      try {
        const count = await client.query(`SELECT COUNT(*) as count FROM "${table}"`);
        const rowCount = parseInt(count.rows[0].count);
        log(`  - ${table}: ${rowCount} rows`, rowCount === 0 ? 'yellow' : 'green');
      } catch (err) {
        log(`  - ${table}: Error checking`, 'red');
      }
    }

    client.release();
    log('\n✓ Database schema verification complete', 'green');

  } catch (error) {
    log(`✗ Database verification failed: ${error.message}`, 'red');
  }
}

