  const controllerFiles = fs.readdirSync(controllersDir).filter(f => f.endsWith('.js') || f.endsWith('.ts'));
  auditResults.controllers.total = controllerFiles.length;

  log(`📁 Found ${controllerFiles.length} controller files`, 'blue');

  // Check for stub/incomplete controllers
  const incompleteControllers = [];

  controllerFiles.forEach(file => {
    const filePath = path.join(controllersDir, file);
    const content = fs.readFileSync(filePath, 'utf8');

    // Check for TODO markers
    if (content.includes('TODO') || content.includes('FIXME') || content.includes('NOT_IMPLEMENTED')) {
      incompleteControllers.push(file);
    }

    // Check for empty/stub functions
    if (content.match(/res\.status\(501\)/) || content.match(/throw new Error\(['"]Not implemented['"]\)/)) {
      if (!incompleteControllers.includes(file)) {
        incompleteControllers.push(file);
      }
    }
