  auditResults.controllers.incomplete = incompleteControllers;

  if (incompleteControllers.length > 0) {
    log(`\n⚠️  Found ${incompleteControllers.length} incomplete controllers:`, 'yellow');
    incompleteControllers.forEach(c => log(`  - ${c}`, 'yellow'));

