  log(`📁 Found ${routeFiles.length} route files`, 'blue');

  // Read app.js to check which routes are registered
  const appContent = fs.readFileSync(appFile, 'utf8');

  const unregisteredRoutes = [];

  routeFiles.forEach(file => {
    const routeName = file.replace(/\.(js|ts)$/, '');
    const importPattern = new RegExp(`require\\(['"].*${routeName}['"]\\)`);
    const usePattern = new RegExp(`app\\.use\\(['"].*${routeName}['"]`);

    if (!importPattern.test(appContent) && !usePattern.test(appContent)) {
      unregisteredRoutes.push(file);
    }
  });

