}

/**
 * Phase 4: Import Verification
 */
function verifyImports() {
  logSection('PHASE 4: IMPORT VERIFICATION');

  const backendDir = __dirname;
  const jsFiles = [];

  // Recursively find all JS/TS files
  function findJSFiles(dir) {
    const items = fs.readdirSync(dir);
    items.forEach(item => {
      const fullPath = path.join(dir, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !item.includes('node_modules') && !item.includes('.git')) {
        findJSFiles(fullPath);
      } else if (stat.isFile() && (item.endsWith('.js') || item.endsWith('.ts'))) {
        jsFiles.push(fullPath);
      }
    });
  }

  findJSFiles(backendDir);
  log(`📁 Scanning ${jsFiles.length} files for broken imports...`, 'blue');

  const brokenImports = [];

  jsFiles.forEach(file => {
    const content = fs.readFileSync(file, 'utf8');
    const importMatches = content.matchAll(/(?:import|require)\(['"]([^'"]+)['"]\)/g);

    for (const match of importMatches) {
      const importPath = match[1];

      // Skip node_modules and relative paths starting with .
      if (importPath.startsWith('.') || importPath.startsWith('node_modules')) continue;

      // Check if it's a local module that exists
      if (!importPath.startsWith('@') && !['express', 'pg', 'redis', 'cors', 'helmet', 'dotenv'].includes(importPath)) {
        try {
          require.resolve(importPath);
        } catch (err) {
          brokenImports.push({ file: path.relative(backendDir, file), import: importPath });
        }
      }
    }
  });

  auditResults.imports.broken = brokenImports;

  if (brokenImports.length > 0) {
    log(`\n⚠️  Found ${brokenImports.length} potentially broken imports`, 'yellow');
    brokenImports.slice(0, 10).forEach(b => {
      log(`  - ${b.file}: ${b.import}`, 'yellow');
    });
    if (brokenImports.length > 10) {
      log(`  ... and ${brokenImports.length - 10} more`, 'yellow');
    }
  } else {
    log('✓ No broken imports detected', 'green');
  }
}

