            userId,
            achievementId: achievement.id,
            progress: metadata || {}
          });

          newlyUnlocked.push({
            achievement: achievement.name,
            tier: achievement.tier,
            reward: achievement.reward
          });
        }
      }

      res.json({
        success: true,
        message: `Checked ${achievements.length} achievements`,
        data: {
          newlyUnlocked,
          count: newlyUnlocked.length
        }
      });
    } catch (error) {
