/**
 * Activity Controller
 * Complete implementation for user activity feed and tracking
 * Date: June 10, 2026 - Phase 1 Week 2 Priority #1
 */

const { socialDb } = require("../db");
const logger = require('../utils/logger');
const User = require('../models/user');
const Post = require('../models/post');
const { Op } = require('sequelize');
const { validationResult } = require('express-validator');

class ActivityController {
  /**
   * GET /api/activity
   * Get user activity feed with pagination
   */
  async getAll(req, res) {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = Math.min(parseInt(req.query.limit) || 20, 100);
      const offset = (page - 1) * limit;

      const userId = req.user?.id;
      const { type, actor_id, date_from, date_to } = req.query;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      // Build activity query
      let query = `
        SELECT 
          a.id,
          a.type,
          a.actor_id,
          a.target_type,
          a.target_id,
          a.metadata,
          a.created_at,
          u.username as actor_username,
          u.avatar_url as actor_avatar
        FROM activities a
        JOIN users u ON a.actor_id = u.id
        WHERE 1=1
      `;

      const params = [];
      let paramIndex = 0;

      // Filter by activity type
      if (type) {
        paramIndex++;
        query += ` AND a.type = $${paramIndex}`;
        params.push(type);
      }

      // Filter by actor
      if (actor_id) {
        paramIndex++;
        query += ` AND a.actor_id = $${paramIndex}`;
        params.push(actor_id);
      }

      // Date range filter
      if (date_from) {
        paramIndex++;
        query += ` AND a.created_at >= $${paramIndex}`;
        params.push(date_from);
      }

      if (date_to) {
        paramIndex++;
        query += ` AND a.created_at <= $${paramIndex}`;
        params.push(date_to);
      }

      // Order by most recent
      query += ` ORDER BY a.created_at DESC`;

      // Add pagination
      paramIndex++;
      query += ` LIMIT $${paramIndex}`;
      params.push(limit);

      paramIndex++;
      query += ` OFFSET $${paramIndex}`;
      params.push(offset);

      const { rows: activities } = await socialDb.query(query, params);

      // Get total count
      let countQuery = `SELECT COUNT(*) as total FROM activities a WHERE 1=1`;
      const countParams = [];
      let countParamIndex = 0;

      if (type) {
        countParamIndex++;
        countQuery += ` AND a.type = $${countParamIndex}`;
        countParams.push(type);
      }

      if (actor_id) {
        countParamIndex++;
        countQuery += ` AND a.actor_id = $${countParamIndex}`;
        countParams.push(actor_id);
      }

      if (date_from) {
        countParamIndex++;
        countQuery += ` AND a.created_at >= $${countParamIndex}`;
        countParams.push(date_from);
      }

      if (date_to) {
        countParamIndex++;
        countQuery += ` AND a.created_at <= $${countParamIndex}`;
        countParams.push(date_to);
      }

      const { rows: countResult } = await socialDb.query(countQuery, countParams);
      const total = parseInt(countResult[0]?.total || 0);
      const totalPages = Math.ceil(total / limit);

      res.json({
        success: true,
        data: activities.map(activity => ({
          id: activity.id,
          type: activity.type,
          actor: {
            id: activity.actor_id,
            username: activity.actor_username,
            avatarUrl: activity.actor_avatar
          },
          targetType: activity.target_type,
          targetId: activity.target_id,
          metadata: activity.metadata,
          createdAt: activity.created_at
        })),
        pagination: {
          page,
          limit,
          total,
          totalPages,
          hasNext: page < totalPages,
          hasPrev: page > 1
        }
      });
    } catch (error) {
      logger.error('Error in ActivityController.getAll:', error);
      res.status(500).json({
        success: false, message: 'Failed to retrieve activity feed', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/activity
   * Create new activity record
   */
  async create(req, res) {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          success: false, message: 'Validation failed',
          errors: errors.array()
        });
      }

      const { type, target_type, target_id, metadata } = req.body;
      const actorId = req.user?.id;

      if (!actorId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      const result = await socialDb.query(
        `INSERT INTO activities (type, actor_id, target_type, target_id, metadata, created_at)
         VALUES ($1, $2, $3, $4, $5, NOW())
         RETURNING *`,
        [type, actorId, target_type, target_id, JSON.stringify(metadata || {})]
      );

      const activity = result.rows[0];

      res.status(201).json({
        success: true, message: 'Activity recorded successfully',
        data: {
          id: activity.id,
          type: activity.type,
          targetType: activity.target_type,
          targetId: activity.target_id createdAt: activity.created_at
        }
      });
    } catch (error) {
      logger.error('Error in ActivityController.create:', error);
      res.status(500).json({
        success: false, message: 'Failed to create activity', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * GET /api/activity/stats
   * Get activity statistics
   */
  async getStats(req, res) {
    try {
      const userId = req.user?.id;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      // Get activity counts by type
      const { rows: typeStats } = await socialDb.query(
        `SELECT type, COUNT(*) as count
         FROM activities
         WHERE actor_id = $1
         GROUP BY type
         ORDER BY count DESC`,
        [userId]
      );

      // Get recent activity count (last 24 hours)
      const { rows: recentCount } = await socialDb.query(
        `SELECT COUNT(*) as count
         FROM activities
         WHERE actor_id = $1
         AND created_at >= NOW() - INTERVAL '24 hours'`,
        [userId]
      );

      // Get total activity count
      const { rows: totalCount } = await socialDb.query(
        `SELECT COUNT(*) as count
         FROM activities
         WHERE actor_id = $1`,
        [userId]
      );

      res.json({
        success: true,
        data: {
          total: parseInt(totalCount[0]?.count || 0),
          last24Hours: parseInt(recentCount[0]?.count || 0),
          byType: typeStats.reduce((acc, stat) => {
            acc[stat.type] = parseInt(stat.count);
            return acc;
          } {})
        }
      });
    } catch (error) {
      logger.error('Error in ActivityController.getStats:', error);
      res.status(500).json({
        success: false, message: 'Failed to retrieve activity statistics', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
}

module.exports = new ActivityController();

/**
 * API Keys Controller
 * Complete implementation for API key CRUD operations
 * Date: June 11, 2026 - Phase 1 Implementation
 */

const { pool } = require('../db');
const logger = require('../utils/logger');
const crypto = require('crypto');

class ApiKeysController {
  /**
   * GET /api/apiKeys
   * Get all API keys for current user
   */
  async getAll(req, res) {
    try {
      const userId = req.user?.id;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      const result = await pool.query(
        `SELECT 
          id,
          name,
          api_key_prefix,
          permissions,
          is_active,
          expires_at,
          created_at,
          last_used_at
         FROM api_keys
         WHERE user_id = $1
         ORDER BY created_at DESC`,
        [userId]
      );

      res.json({
        success: true,
        data: result.rows.map(key => ({
          ...key, permissions: typeof key.permissions === 'string' ? JSON.parse(key.permissions) : key.permissions
        })), count: result.rows.length
      });
    } catch (error) {
      logger.error('Error in ApiKeysController.getAll:', error);
      res.status(500).json({
        success: false, message: 'Failed to get API keys', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/apiKeys
   * Create new API key
   */
  async create(req, res) {
    try {
      const userId = req.user?.id;
      const { name, permissions, expiryDays } = req.body;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      // Generate API key
      const apiKey = `fk_${crypto.randomBytes(32).toString('hex')}`;
      const keyId = crypto.randomUUID();
      const keyPrefix = apiKey.substring(0, 8);

      // Calculate expiry
      const expiresAt = expiryDays 
        ? new Date(Date.now() + parseInt(expiryDays) * 24 * 60 * 60 * 1000)
        : null;

      await pool.query(
        `INSERT INTO api_keys 
         (id, user_id, name, api_key, api_key_prefix, permissions, expires_at, is_active, created_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7, true, NOW())`,
        [
          keyId,
          userId name || 'API Key',
          apiKey,
          keyPrefix JSON.stringify(permissions || ['read']),
          expiresAt
        ]
      );

      res.status(201).json({
        success: true, message: 'API key created successfully',
        data: {
          id: keyId, name: name || 'API Key',
          apiKey: apiKey, // Only shown once
          keyPrefix: keyPrefix, permissions: permissions || ['read'],
          createdAt: new Date(),
          expiresAt: expiresAt, warning: 'Store this API key securely. It will not be shown again.'
        }
      });
    } catch (error) {
      logger.error('Error in ApiKeysController.create:', error);
      res.status(500).json({
        success: false, message: 'Failed to create API key', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * PUT /api/apiKeys/:id
   * Update API key
   */
  async update(req, res) {
    try {
      const userId = req.user?.id;
      const { id } = req.params;
      const updates = req.body;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      const setClauses = [];
      const values = [];
      let paramCount = 1;

      Object.keys(updates).forEach(key => {
        if (['name', 'permissions', 'is_active'].includes(key)) {
          if (key === 'permissions') {
            setClauses.push(`${key} = $${paramCount}`);
            values.push(JSON.stringify(updates[key]));
          } else {
            setClauses.push(`${key} = $${paramCount}`);
            values.push(updates[key]);
          }
          paramCount++;
        }
      });

      if (setClauses.length === 0) {
        return res.status(400).json({
          success: false, message: 'No valid fields to update'
        });
      }

      setClauses.push('updated_at = NOW()');
      values.push(id, userId);

      const result = await pool.query(
        `UPDATE api_keys 
         SET ${setClauses.join(', ')}
         WHERE id = $${paramCount} AND user_id = $${paramCount + 1}
         RETURNING *`,
        values
      );

      if (result.rows.length === 0) {
        return res.status(404).json({
          success: false, message: 'API key not found'
        });
      }

      res.json({
        success: true, message: 'API key updated successfully', data: result.rows[0]
      });
    } catch (error) {
      logger.error('Error in ApiKeysController.update:', error);
      res.status(500).json({
        success: false, message: 'Failed to update API key', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * DELETE /api/apiKeys/:id
   * Delete/Revoke API key
   */
  async delete(req, res) {
    try {
      const userId = req.user?.id;
      const { id } = req.params;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      const result = await pool.query(
        'DELETE FROM api_keys WHERE id = $1 AND user_id = $2 RETURNING id',
        [id, userId]
      );

      if (result.rows.length === 0) {
        return res.status(404).json({
          success: false, message: 'API key not found'
        });
      }

      res.json({
        success: true, message: 'API key revoked successfully'
      });
    } catch (error) {
      logger.error('Error in ApiKeysController.delete:', error);
      res.status(500).json({
        success: false, message: 'Failed to revoke API key', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/apiKeys/:id/rotate
   * Rotate API key (generate new key, keep same ID)
   */
  async rotateKey(req, res) {
    try {
      const userId = req.user?.id;
      const { id } = req.params;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      // Generate new API key
      const newApiKey = `fk_${crypto.randomBytes(32).toString('hex')}`;
      const newKeyPrefix = newApiKey.substring(0, 8);

      const result = await pool.query(
        `UPDATE api_keys 
         SET api_key = $1, api_key_prefix = $2, rotated_at = NOW(), updated_at = NOW()
         WHERE id = $3 AND user_id = $4
         RETURNING *`,
        [newApiKey, newKeyPrefix, id, userId]
      );

      if (result.rows.length === 0) {
        return res.status(404).json({
          success: false, message: 'API key not found'
        });
      }

      res.json({
        success: true, message: 'API key rotated successfully',
        data: {
          id: result.rows[0].id,
          apiKey: newApiKey, // Only shown once
          keyPrefix: newKeyPrefix,
          rotatedAt: new Date() warning: 'Update your applications with the new API key immediately'
        }
      });
    } catch (error) {
      logger.error('Error in ApiKeysController.rotateKey:', error);
      res.status(500).json({
        success: false, message: 'Failed to rotate API key', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
}

