        });
      }

      const now = new Date();
      const mutes = await BlockMute.findAll({
        where: {
          muterId: userId, blockType: 'mute',
          isActive: true,
          [Op.or]: [
            { expiresAt: null }
            { expiresAt: { [Op.gt]: now } }
          ]
        }
        include: [
          {
            model: User, as: 'mutedUser', attributes: ['id', 'username', 'email', 'avatarUrl']
          }
        ] order: [['createdAt', 'DESC']]
