/**
 * GemsController
 * Digital collectibles and virtual currency management
 */

const pool = require('../database/connection');
const logger = require('../utils/logger');

class GemsController {
  /**
   * GET /api/gems/balance
   * Get user's gem balance
   */
  async getBalance(req, res) {
    try {
      const userId = req.user?.id || req.user?.userId;

      const query = `
        SELECT COALESCE(SUM(
          CASE 
            WHEN type IN ('earned', 'purchased', 'gifted') THEN amount
            WHEN type IN ('spent', 'transferred') THEN -amount
            ELSE 0
          END
        ), 0) as balance
        FROM gem_transactions
        WHERE user_id = $1
      `;

      const result = await pool.query(query, [userId]);

      res.json({
        success: true, message: 'Balance retrieved',
        data: {
          balance: parseFloat(result.rows[0].balance) || 0, currency: 'GEMS'
        }
      });
    } catch (error) {
      logger.error('Error in GemsController.getBalance:', error);
      res.status(500).json({
        success: false, error: 'Failed to retrieve balance',
        details: error.message
      });
    }
  }

  /**
   * GET /api/gems/transactions
   * Get transaction history
   */
  async getTransactions(req, res) {
    try {
      const userId = req.user?.id || req.user?.userId;
      const limit = parseInt(req.query.limit) || 50;
      const offset = parseInt(req.query.offset) || 0;

      const query = `
        SELECT * FROM gem_transactions
        WHERE user_id = $1
        ORDER BY created_at DESC
        LIMIT $2 OFFSET $3
      `;

      const result = await pool.query(query, [userId, limit, offset]);

      res.json({
        success: true, message: 'Transactions retrieved',
        data: {
          transactions: result.rows,
          total: result.rows.length,
          limit offset
        }
      });
    } catch (error) {
      logger.error('Error in GemsController.getTransactions:', error);
      res.status(500).json({
        success: false, error: 'Failed to retrieve transactions',
        details: error.message
      });
    }
  }

  /**
   * POST /api/gems/award
   * Award gems to user
   */
  async award(req, res) {
    try {
      const userId = req.user?.id || req.user?.userId;
      const { amount, reason, metadata = {} } = req.body;

      if (!amount || amount <= 0) {
        return res.status(400).json({
          success: false, error: 'Valid amount is required'
        });
      }

      const query = `
        INSERT INTO gem_transactions (user_id, type, amount, description, metadata, created_at)
        VALUES ($1, 'earned', $2, $3, $4, NOW())
        RETURNING *
      `;

      const result = await pool.query(query, [
        userId,
        amount reason || 'Gem award',
        JSON.stringify(metadata)
      ]);

      res.status(201).json({
        success: true, message: 'Gems awarded', data: result.rows[0]
      });
    } catch (error) {
      logger.error('Error in GemsController.award:', error);
      res.status(500).json({
        success: false, error: 'Failed to award gems',
        details: error.message
      });
    }
  }

  /**
   * POST /api/gems/deduct
   * Deduct gems from user
   */
  async deduct(req, res) {
    try {
      const userId = req.user?.id || req.user?.userId;
      const { amount, reason } = req.body;

      if (!amount || amount <= 0) {
        return res.status(400).json({
          success: false, error: 'Valid amount is required'
        });
      }

      // Check balance first
      const balanceQuery = `
        SELECT COALESCE(SUM(
          CASE 
            WHEN type IN ('earned', 'purchased', 'gifted') THEN amount
            WHEN type IN ('spent', 'transferred') THEN -amount
            ELSE 0
          END
        ), 0) as balance
        FROM gem_transactions
        WHERE user_id = $1
      `;

      const balanceResult = await pool.query(balanceQuery, [userId]);
      const balance = parseFloat(balanceResult.rows[0].balance) || 0;

      if (balance < amount) {
        return res.status(402).json({
          success: false, error: 'Insufficient gems', data: { available: balance, required: amount }
        });
      }

      const query = `
        INSERT INTO gem_transactions (user_id, type, amount, description, created_at)
        VALUES ($1, 'spent', $2, $3, NOW())
        RETURNING *
      `;

      const result = await pool.query(query, [userId, amount, reason || 'Gem deduction']);

      res.json({
        success: true, message: 'Gems deducted', data: result.rows[0]
      });
    } catch (error) {
      logger.error('Error in GemsController.deduct:', error);
      res.status(500).json({
        success: false, error: 'Failed to deduct gems',
        details: error.message
      });
    }
  }

  /**
   * POST /api/gems/transfer
   * Transfer gems between users
   */
  async transfer(req, res) {
    try {
      const fromUserId = req.user?.id || req.user?.userId;
      const { to_user_id, amount, message } = req.body;

      if (!to_user_id || !amount || amount <= 0) {
        return res.status(400).json({
          success: false, error: 'Recipient ID and valid amount are required'
        });
      }

      if (fromUserId === to_user_id) {
        return res.status(400).json({
          success: false, error: 'Cannot transfer to yourself'
        });
      }

      const client = await pool.connect();

      try {
        await client.query('BEGIN');

        // Check sender balance
        const balanceQuery = `
          SELECT COALESCE(SUM(
            CASE 
              WHEN type IN ('earned', 'purchased', 'gifted') THEN amount
              WHEN type IN ('spent', 'transferred') THEN -amount
              ELSE 0
            END
          ), 0) as balance
          FROM gem_transactions
          WHERE user_id = $1
        `;

        const balanceResult = await client.query(balanceQuery, [fromUserId]);
        const balance = parseFloat(balanceResult.rows[0].balance) || 0;

        if (balance < amount) {
          throw new Error('Insufficient gems');
        }

        // Debit from sender
        await client.query(`
          INSERT INTO gem_transactions (user_id, type, amount, description, created_at)
          VALUES ($1, 'transferred', $2, $3, NOW())
        `, [fromUserId, amount, `Transfer to user ${to_user_id}: ${message || ''}`]);

        // Credit to recipient
        await client.query(`
          INSERT INTO gem_transactions (user_id, type, amount, description, created_at)
          VALUES ($1, 'gifted', $2, $3, NOW())
        `, [to_user_id, amount, `Gift from user ${fromUserId}: ${message || ''}`]);

        await client.query('COMMIT');

        res.json({
          success: true, message: 'Transfer completed',
          data: {
            from: fromUserId,
            to: to_user_id,
            amount message
          }
        });
      } catch (error) {
        await client.query('ROLLBACK');
        throw error;
      } finally {
        client.release();
      }
    } catch (error) {
      logger.error('Error in GemsController.transfer:', error);

      if (error.message === 'Insufficient gems') {
        return res.status(402).json({
          success: false,
          error: error.message
        });
      }

      res.status(500).json({
        success: false, error: 'Transfer failed',
        details: error.message
      });
    }
  }
}

module.exports = new GemsController();

/**
 * GiftCards Controller
 * Complete implementation for gift card management
 * Date: June 10, 2026 - Phase 1 Week 1 Priority #1
 */

const GiftCard = require('../models/giftcard');
const logger = require('../utils/logger');
const User = require('../models/user');
const { Op } = require('sequelize');
const { body, validationResult } = require('express-validator');

class GiftCardsController {
  /**
   * GET /api/giftcards
   * Get all gift cards with pagination and filtering
   */
  async getAll(req, res) {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = Math.min(parseInt(req.query.limit) || 20, 100); // Max 100 per page
      const offset = (page - 1) * limit;

      // Build filters
      const where = {};
      if (req.query.status) where.status = req.query.status;
      if (req.query.currency) where.currency = req.query.currency;
      if (req.query.purchasedBy) where.purchasedBy = req.query.purchasedBy;

      // Fetch data with pagination
      const { count, rows: data } = await GiftCard.findAndCountAll({
        where,
        limit,
        offset, order: [['createdAt', 'DESC']],
        include: [
          {
            model: User, as: 'purchaser', attributes: ['id', 'username', 'email']
          },
          {
            model: User, as: 'redeemer', attributes: ['id', 'username', 'email'],
            required: false
          }
        ]
      });

      // Format response
      const totalPages = Math.ceil(count / limit);

      res.json({
        success: true,
        data: data.map(giftCard => ({
          id: giftCard.id,
          code: giftCard.code,
          amount: parseFloat(giftCard.amount),
          currency: giftCard.currency,
          status: giftCard.status,
          expiryDate: giftCard.expiryDate,
          redeemedAt: giftCard.redeemedAt,
          description: giftCard.description,
          purchaser: giftCard.purchaser,
          redeemer: giftCard.redeemer,
          createdAt: giftCard.createdAt,
          updatedAt: giftCard.updatedAt
        })),
        pagination: {
          page,
          limit,
          total: count,
          totalPages,
          hasNext: page < totalPages,
          hasPrev: page > 1
        },
        links: {
          self: `/api/giftcards?page=${page}&limit=${limit}`,
          next: page < totalPages ? `/api/giftcards?page=${page + 1}&limit=${limit}` : null,
          prev: page > 1 ? `/api/giftcards?page=${page - 1}&limit=${limit}` : null,
          first: `/api/giftcards?page=1&limit=${limit}`, last: `/api/giftcards?page=${totalPages}&limit=${limit}`
        }
      });
    } catch (error) {
      logger.error('Error in GiftCardsController.getAll:', error);
      res.status(500).json({
        success: false, message: 'Failed to retrieve gift cards', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * GET /api/giftcards/:id
   * Get gift card by ID
   */
  async getById(req, res) {
    try {
      const { id } = req.params;

      const giftCard = await GiftCard.findByPk(id, {
        include: [
          {
            model: User, as: 'purchaser', attributes: ['id', 'username', 'email']
          },
          {
            model: User, as: 'redeemer', attributes: ['id', 'username', 'email'],
            required: false
          }
        ]
      });

      if (!giftCard) {
        return res.status(404).json({
          success: false, message: 'Gift card not found'
        });
      }

      res.json({
        success: true,
        data: {
          id: giftCard.id,
          code: giftCard.code,
          amount: parseFloat(giftCard.amount),
          currency: giftCard.currency,
          status: giftCard.status,
          expiryDate: giftCard.expiryDate,
          redeemedAt: giftCard.redeemedAt,
          description: giftCard.description,
          purchaser: giftCard.purchaser,
          redeemer: giftCard.redeemer,
          createdAt: giftCard.createdAt, updatedAt: giftCard.updatedAt
        }
      });
    } catch (error) {
      logger.error('Error in GiftCardsController.getById:', error);
      res.status(500).json({
        success: false, message: 'Failed to retrieve gift card', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/giftcards
   * Create new gift card
   */
  async create(req, res) {
    try {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          success: false, message: 'Validation failed',
          errors: errors.array()
        });
      }

      const { amount, currency, expiryDate, description, purchasedBy } = req.body;

      // Generate unique code
      let code;
      let isUnique = false;
      while (!isUnique) {
        code = GiftCard.generateCode();
        const existing = await GiftCard.findOne({ where: { code } });
        if (!existing) isUnique = true;
      }

      // Create gift card
      const giftCard = await GiftCard.create({
        code,
        amount currency: currency || 'NGN',
        expiryDate: expiryDate ? new Date(expiryDate) : null,
        description,
        purchasedBy: purchasedBy || req.user?.id
      });

      res.status(201).json({
        success: true, message: 'Gift card created successfully',
        data: {
          id: giftCard.id,
          code: giftCard.code,
          amount: parseFloat(giftCard.amount),
          currency: giftCard.currency,
          status: giftCard.status,
          expiryDate: giftCard.expiryDate,
          description: giftCard.description createdAt: giftCard.createdAt
        }
      });
    } catch (error) {
      logger.error('Error in GiftCardsController.create:', error);
      res.status(500).json({
        success: false, message: 'Failed to create gift card', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/giftcards/:id/redeem
   * Redeem a gift card
   */
  async redeem(req, res) {
    try {
      const { id } = req.params;
      const userId = req.user?.id;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      const giftCard = await GiftCard.findByPk(id);

      if (!giftCard) {
        return res.status(404).json({
          success: false, message: 'Gift card not found'
        });
      }

      try {
        await giftCard.redeem(userId);

        res.json({
          success: true, message: 'Gift card redeemed successfully',
          data: {
            id: giftCard.id,
            code: giftCard.code,
            amount: parseFloat(giftCard.amount),
            currency: giftCard.currency,
            status: giftCard.status,
            redeemedAt: giftCard.redeemedAt
          }
        });
      } catch (redeemError) {
        return res.status(400).json({
          success: false, message: redeemError.message
        });
      }
    } catch (error) {
      logger.error('Error in GiftCardsController.redeem:', error);
      res.status(500).json({
        success: false, message: 'Failed to redeem gift card', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * PUT /api/giftcards/:id
   * Update gift card
   */
  async update(req, res) {
    try {
      const { id } = req.params;
      const { amount, expiryDate, description, status } = req.body;

      const giftCard = await GiftCard.findByPk(id);

      if (!giftCard) {
        return res.status(404).json({
          success: false, message: 'Gift card not found'
        });
      }

      // Only allow updates to certain fields
      const updates = {};
      if (amount !== undefined) updates.amount = amount;
      if (expiryDate !== undefined) updates.expiryDate = new Date(expiryDate);
      if (description !== undefined) updates.description = description;
      if (status !== undefined && ['active', 'cancelled'].includes(status)) {
        updates.status = status;
      }

      await giftCard.update(updates);

      res.json({
        success: true, message: 'Gift card updated successfully',
        data: {
          id: giftCard.id,
          code: giftCard.code,
          amount: parseFloat(giftCard.amount),
          currency: giftCard.currency,
          status: giftCard.status,
          expiryDate: giftCard.expiryDate,
          description: giftCard.description updatedAt: giftCard.updatedAt
        }
      });
    } catch (error) {
      logger.error('Error in GiftCardsController.update:', error);
      res.status(500).json({
        success: false, message: 'Failed to update gift card', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * DELETE /api/giftcards/:id
   * Cancel/delete gift card
   */
  async delete(req, res) {
    try {
      const { id } = req.params;

      const giftCard = await GiftCard.findByPk(id);

      if (!giftCard) {
        return res.status(404).json({
          success: false, message: 'Gift card not found'
        });
      }

      // Only active cards can be cancelled
      if (giftCard.status !== 'active') {
        return res.status(400).json({
          success: false, message: 'Only active gift cards can be cancelled'
        });
      }

      await giftCard.update({ status: 'cancelled' });

      res.json({
        success: true, message: 'Gift card cancelled successfully'
      });
    } catch (error) {
      logger.error('Error in GiftCardsController.delete:', error);
      res.status(500).json({
        success: false, message: 'Failed to cancel gift card', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * GET /api/giftcards/stats
   * Get gift card statistics
   */
  async getStats(req, res) {
    try {
      const stats = await GiftCard.findAll({
        attributes: [
          'status' [sequelize.fn('COUNT', sequelize.col('id')), 'count'] [sequelize.fn('SUM', sequelize.col('amount')), 'total_amount']
        ] group: ['status']
      });

      const summary = {
        total: await GiftCard.count(),
        byStatus: {}
        totalValue: 0
      };

      stats.forEach(stat => {
        summary.byStatus[stat.status] = {
          count: parseInt(stat.dataValues.count),
          totalAmount: parseFloat(stat.dataValues.total_amount || 0)
        };
        summary.totalValue += parseFloat(stat.dataValues.total_amount || 0);
      });

      res.json({
        success: true, data: summary
      });
    } catch (error) {
      logger.error('Error in GiftCardsController.getStats:', error);
      res.status(500).json({
        success: false, message: 'Failed to retrieve statistics', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
}

module.exports = new GiftCardsController();

/**
 * Voice Feed Controller
 * Complete implementation for voice/audio feed platform
 * Date: June 11, 2026 - Phase 1 Implementation
 */

const { pool } = require('../db');
const logger = require('../utils/logger');

class VoiceFeedController {
  /**
   * GET /api/voicefeed/posts
   * Get voice posts/feed
   */
  async getPosts(req, res) {
    try {
      const { limit = 50, offset = 0, category, sortBy = 'created_at' } = req.query;

      let whereClause = ['is_published = true'];
      let queryParams = [];
      let paramCount = 1;

      if (category) {
        whereClause.push(`category = $${paramCount}`);
        queryParams.push(category);
        paramCount++;
      }

      const whereSQL = whereClause.join(' AND ');

      const result = await pool.query(`SELECT 
          v.*,
          u.username as author_username,
          u.avatar_url as author_avatar,
          COUNT(DISTINCT l.id) as likes_count,
          COUNT(DISTINCT c.id) as comments_count, COUNT(DISTINCT p.id) as plays_count
         FROM voicefeed_posts v
         JOIN users u ON v.author_id = u.id
         LEFT JOIN likes l ON l.target_id = v.id AND l.target_type = 'voice_post'
         LEFT JOIN voicefeed_comments c ON c.post_id = v.id
         LEFT JOIN voicefeed_plays p ON p.post_id = v.id
         WHERE $1
         GROUP BY v.id, u.username, u.avatar_url
         ORDER BY v.${sortBy} DESC
         LIMIT $${paramCount} OFFSET $${paramCount + 1}`, [...queryParams, parseInt(limit), parseInt(offset), whereSQL]);

      res.json({
        success: true,
        data: result.rows.map(post => ({
          ...post,
          durationSeconds: parseInt(post.duration_seconds),
          likesCount: parseInt(post.likes_count),
          commentsCount: parseInt(post.comments_count),
          playsCount: parseInt(post.plays_count)
        })),
        pagination: {
          limit: parseInt(limit),
          offset: parseInt(offset) total: result.rows.length
        }
      });
    } catch (error) {
      logger.error('Error in VoiceFeedController.getPosts:', error);
      res.status(500).json({
        success: false, message: 'Failed to get voice posts', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/voicefeed/posts
   * Create voice post
   */
  async createPost(req, res) {
    try {
      const userId = req.user?.id;
      const { title, audioUrl, durationSeconds, category, tags } = req.body;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      if (!title || !audioUrl) {
        return res.status(400).json({
          success: false, message: 'Title and audio URL are required'
        });
      }

      const result = await pool.query(
        `INSERT INTO voicefeed_posts 
         (author_id, title, audio_url, duration_seconds, category, tags, is_published, created_at)
         VALUES ($1, $2, $3, $4, $5, $6, true, NOW())
         RETURNING *`,
        [
          userId,
          title,
          audioUrl,
          durationSeconds ? parseInt(durationSeconds) : null,
          category || null,
          JSON.stringify(tags || [])
        ]
      );

      res.status(201).json({
        success: true, message: 'Voice post created successfully', data: result.rows[0]
      });
    } catch (error) {
      logger.error('Error in VoiceFeedController.createPost:', error);
      res.status(500).json({
        success: false, message: 'Failed to create voice post', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/voicefeed/posts/:id/play
   * Record voice post play
   */
  async recordPlay(req, res) {
    try {
      const userId = req.user?.id;
      const { id: postId } = req.params;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      await pool.query(
        `INSERT INTO voicefeed_plays (user_id, post_id, played_at)
         VALUES ($1, $2, NOW())`,
        [userId, postId]
      );

      res.json({
        success: true, message: 'Play recorded'
      });
    } catch (error) {
      logger.error('Error in VoiceFeedController.recordPlay:', error);
      res.status(500).json({
        success: false, message: 'Failed to record play', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * GET /api/voicefeed/trending
   * Get trending voice posts
   */
  async getTrending(req, res) {
    try {
      const { limit = 20, timeframe = '7d' } = req.query;

      let timeFilter = '';
      if (timeframe === '24h') {
        timeFilter = 'AND vp.played_at >= NOW() - INTERVAL \'24 hours\'';
      } else if (timeframe === '7d') {
        timeFilter = 'AND vp.played_at >= NOW() - INTERVAL \'7 days\'';
      }

      const result = await pool.query('SELECT 
          v.*,
          u.username as author_username,
          u.avatar_url as author_avatar,
          COUNT(DISTINCT vp.id) as plays_count COUNT(DISTINCT l.id) as likes_count
         FROM voicefeed_posts v
         JOIN users u ON v.author_id = u.id
         LEFT JOIN voicefeed_plays vp ON v.id = vp.post_id $1
         LEFT JOIN likes l ON l.target_id = v.id AND l.target_type = 'voice_post'
         WHERE v.is_published = true
         GROUP BY v.id, u.username, u.avatar_url
         ORDER BY plays_count DESC
         LIMIT $1', [parseInt(limit), timeFilter]);

      res.json({
        success: true,
        data: result.rows.map(post => ({
          ...post,
          durationSeconds: parseInt(post.duration_seconds),
          playsCount: parseInt(post.plays_count) likesCount: parseInt(post.likes_count)
        }))
      });
    } catch (error) {
      logger.error('Error in VoiceFeedController.getTrending:', error);
      res.status(500).json({
        success: false, message: 'Failed to get trending posts', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
}

