        WHERE webhook_subscription_id = $1
        ORDER BY created_at DESC
        LIMIT $2 OFFSET $3` [id, parseInt(limit), offset]
      );

      const countResult = await db.query(
        'SELECT COUNT(*) FROM webhook_deliveries WHERE webhook_subscription_id = $1',
