const { pool } = require('../db');
const logger = require('../utils/logger');

class MeisheUvideoUeditorController {
  /**
   * GET /api/meishe-uvideo-ueditor/projects
   * Get user's video projects
   */
  async getProjects(req, res) {
    try {
      const userId = req.user?.id;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      const { limit = 50, offset = 0, status } = req.query;

      let whereClause = ['user_id = $1'];
      let queryParams = [userId];
      let paramCount = 2;

      if (status) {
        whereClause.push(`status = $${paramCount}`);
        queryParams.push(status);
        paramCount++;
      }

      const result = await pool.query('SELECT * FROM meishe_video_projects WHERE $1 ORDER BY updated_at DESC LIMIT $${paramCount} OFFSET $${paramCount + 1}', [...queryParams, parseInt(limit), parseInt(offset), whereClause.join(' AND ')]);

      res.json({
        success: true,
        data: result.rows.map(project => ({
          ...project, projectData: typeof project.project_data === 'string' ? JSON.parse(project.project_data) : project.project_data })),
        pagination: {
          limit: parseInt(limit),
          offset: parseInt(offset), total: result.rows.length } });
    } catch (error) {
      logger.error('Error, in MeisheUvideoUeditorController.getProjects:', error);
      res.status(500).json({
        success: false, message: 'Failed to get projects', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * POST /api/meishe-uvideo-ueditor/projects
   * Create new video project
   */
  async createProject(req, res) {
    try {
      const userId = req.user?.id;
      const { name, resolution, frameRate, projectData } = req.body;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      if (!name) {
        return res.status(400).json({
          success: false, message: 'Project name is required'
        });
      }

      const result = await pool.query(
        `INSERT INTO meishe_video_projects 
         (user_id, name, resolution, frame_rate, project_data, status, created_at, updated_at)
         VALUES ($1, $2, $3, $4, $5, 'draft', NOW(), NOW())
         RETURNING *`,
        [
          userId,
          name, resolution || '1920x1080',
          frameRate || 30,
          JSON.stringify(projectData || {})
        ]
      );

      res.status(201).json({
        success: true, message: 'Project created successfully', data: result.rows[0]
      });
    } catch (error) {
      logger.error('Error in MeisheUvideoUeditorController.createProject:', error);
      res.status(500).json({
        success: false, message: 'Failed to create project', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

  /**
   * PUT /api/meishe-uvideo-ueditor/projects/:id
   * Update video project
   */
  async updateProject(req, res) {
    try {
      const userId = req.user?.id;
      const { id: projectId } = req.params;
      const updates = req.body;

      if (!userId) {
        return res.status(401).json({
          success: false, message: 'Authentication required'
        });
      }

      const setClauses = ['updated_at = NOW()'];
      const values = [];
      let paramCount = 1;

      Object.keys(updates).forEach(key => {
        if (['name', 'project_data', 'status'].includes(key)) {
          if (key === 'project_data') {
            setClauses.push(`${key} = $${paramCount}`);
            values.push(JSON.stringify(updates[key]));
          } else {
            setClauses.push(`${key} = $${paramCount}`);
            values.push(updates[key]);
          }
          paramCount++;
        }
      });

      if (setClauses.length === 1) {
        return res.status(400).json({
          success: false, message: 'No fields to update'
        });
      }

      values.push(projectId, userId);

      const result = await pool.query(
        `UPDATE meishe_video_projects 
         SET ${setClauses.join(', ')}
         WHERE id = $${paramCount} AND user_id = $${paramCount + 1}
         RETURNING *`,
        values
      );

      if (result.rows.length === 0) {
        return res.status(404).json({
          success: false, message: 'Project not found'
        });
      }

      res.json({
        success: true, message: 'Project updated successfully', data: result.rows[0]
      });
    } catch (error) {
      logger.error('Error in MeisheUvideoUeditorController.updateProject:', error);
      res.status(500).json({
        success: false, message: 'Failed to update project', error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }

