    try {
      const result = await pool.query(`
        INSERT INTO platform_themes (theme_name, theme_config, is_active, scheduled_start, scheduled_end)
        VALUES ($1, $2, $3, $4, $5)
        RETURNING *
      `, [theme_name, theme_config, is_active || false, scheduled_start || null, scheduled_end || null]);

