// Middleware to check if user is admin or superadmin
const requireAdmin = async (req, res, next) => {
  try {
    // First run the authenticate middleware
    await new Promise((resolve, reject) => {
      authenticate(req, res, (err) => {
        if (err) reject(err);
        else resolve();
      });
    });

    // Check if user has admin or superadmin role
    if (req.user.role !== 'admin' && req.user.role !== 'superadmin') {
      return res.status(403).json({
        success: false,
        message: 'Access denied. Admin privileges required.'
      });
    }

    next();
  } catch (error) {
    if (error.status) {
      return res.status(error.status).json({
        success: false,
        message: error.message
      });
    }
    return res.status(403).json({
      success: false,
      message: 'Authentication required'
    });
  }
};

// Middleware to check if user has specific role
const requireRole = (roles) => {
  return async (req, res, next) => {
    try {
      // First run the authenticate middleware
      await new Promise((resolve, reject) => {
        authenticate(req, res, (err) => {
          if (err) reject(err);
          else resolve();
        });
      });

      // Check if user has one of the required roles
      if (!roles.includes(req.user.role)) {
        return res.status(403).json({
          success: false,
          message: `Access denied. Required role(s): ${roles.join(', ')}`
        });
      }

      next();
    } catch (error) {
      if (error.status) {
        return res.status(error.status).json({
          success: false,
          message: error.message
        });
      }
      return res.status(403).json({
        success: false,
        message: 'Authentication required'
      });
    }
  };
};

// Middleware to check if TOTP is enabled for a user
const checkTOTPEnabled = async (req, res, next) => {
  try {
    const token = req.header('Authorization')?.replace('Bearer ', '');

    if (!token) {
      return res.status(401).json({
        success: false,
        message: 'No token, authorization denied'
      });
    }

    try {
      jwt.verify(token, JWT_SECRET);
    } catch (error) {
      if (error instanceof jwt.TokenExpiredError) {
        return res.status(401).json({
          success: false,
          message: 'Token has expired'
        });
      } else if (error instanceof jwt.JsonWebTokenError) {
        return res.status(401).json({
          success: false,
          message: 'Invalid token'
        });
      } else {
        return res.status(401).json({
          success: false,
          message: 'Token verification failed'
        });
      }
    }

    req.totpEnabled = false;
    next();
  } catch (error) {
    getLogger().error('TOTP Check Error:', error);
    return res.status(500).json({
      success: false,
      message: 'Internal server error during TOTP check'
    });
  }
};

// Middleware to check if user has registration lock enabled
const checkRegistrationLock = async (req, res, next) => {
  try {
    // Get user from the JWT token (this should be called after authenticate middleware)
    const userId = req.user?.id;

    if (!userId) {
      return res.status(401).json({
        error: 'User not authenticated'
      });
    }

    // Check if user has a registration lock
    // Note: RegistrationLockService needs to be properly implemented
    const hasLock = false; // Default to false until RegistrationLockService is properly implemented

    if (hasLock) {
      // Check if the PIN has been verified in this session
      if (!req.session || !req.session.pinVerified) {
        return res.status(403).json({
          error: 'Registration lock active',
          requiresPin: true,
          message: 'PIN verification required to access this resource'
        });
      }
    }

    next();
  } catch (error) {
    getLogger().error('Registration Lock Check, Error:', error);
    return res
      .status(500)
      .json({
        error: 'Error checking registration lock status'
      });
  }
};

module.exports = {
  authenticate,
  authenticateToken, // Adding the authenticateToken export
  requireAdmin,
  requireRole
};

const logger = require('../utils/logger');

/**
 * Global error handling middleware
 */
const errorHandler = (err, req, res, next) => {
  // Log error with context
  if (logger && logger.logError) {
    logger.logError(err, {
      method: req.method,
      url: req.originalUrl,
      ip: req.ip,
      userId: req.user?.id || null,
      body: req.body,
      params: req.params,
      query: req.query
    });
  } else {
    logger.error('❌ Error:', err.message);
    logger.error(err.stack);
  }

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send response
  res.status(statusCode).json({
    success: false,
    error: {
      message: process.env.NODE_ENV === 'production' && statusCode === 500
        ? 'Internal server error'
        : err.message || 'Unknown error',
      ...(process.env.NODE_ENV !== 'production' && {
        stack: err.stack })
    }
  });
};

module.exports = { errorHandler };

const Sentry = require('@sentry/node');
const logger = require('../utils/logger');

// Initialize Sentry if DSN is provided
let sentryInitialized = false;
if (process.env.SENTRY_DSN) {
  try {
    Sentry.init({
      dsn: process.env.SENTRY_DSN,
      environment: process.env.NODE_ENV || 'development',
      tracesSampleRate: process.env.NODE_ENV === 'production' ? 0.1 : 1.0
    });
    sentryInitialized = true;
    logger.info('✅ Sentry initialized');
  } catch (error) {
    console.warn('⚠️  Sentry initialization failed:', error.message);
    console.warn('   Continuing without error tracking...');
  }
} else {
  console.log('ℹ️  Sentry not configured (SENTRY_DSN not set)');
}

/**
 * Request handler - must be used before routes
 */
const sentryRequestHandler = sentryInitialized ? Sentry.Handlers.requestHandler() : (req, res, next) => next();

/**
 * Tracing handler - must be used after requestHandler but before routes
 */
const sentryTracingHandler = sentryInitialized && Sentry.Handlers.tracingHandler ? Sentry.Handlers.tracingHandler() : (req, res, next) => next();

/**
 * Error handler - must be used after routes
 */
const sentryErrorHandler = (err, req, res, next) => {
  if (sentryInitialized) {
    Sentry.captureException(err);
  }

  logger.error('ERROR:', err.stack);

  res.status(err.status || 500).json({
    success: false,
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
    ...(process.env.NODE_ENV !== 'production' && {
      stack: err.stack })
  });
};

module.exports = {
  sentryRequestHandler,
  sentryTracingHandler,
  sentryErrorHandler
};

/**
 * InputValidationMiddleware
 * Centralized input validation and sanitization for all API endpoints
 * Uses express-validator for schema-based validation
 */

const { body, param, query, header, validationResult } = require('express-validator');

class InputValidationMiddleware {

  /**
   * Handle validation errors consistently
   */
  static handleValidationErrors(req, res, next) {
    const errors = validationResult(req);

    if (!errors.isEmpty()) {
      return res.status(400).json({
        success: false,
        message: 'Validation failed',
        errors: errors.array().map(err => ({
          field: err.path,
          message: err.msg,
          value: err.value,
          location: err.location
        }))
      });
    }

    next();
  }

  /**
   * Common validation rules for ID parameters
   */
  static validateId(paramName = 'id') {
    return [
      param(paramName)
        .isUUID()
        .withMessage(`Invalid ${paramName} format - must be UUID`),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate email addresses
   */
  static validateEmail(fieldName = 'email') {
    return [
      body(fieldName)
        .isEmail()
        .normalizeEmail()
        .withMessage('Valid email address is required'),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate phone numbers
   */
  static validatePhone(fieldName = 'phone') {
    return [
      body(fieldName)
        .optional()
        .isMobilePhone('any', { strictMode: false })
        .withMessage('Invalid phone number format'),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate string fields with length limits
   */
  static validateString(fieldName, options = {}) {
    const {
      required = true,
      minLength = 1,
      maxLength = 500,
      trim = true,
      pattern = null,
      message = `Invalid ${fieldName}`
    } = options;

    let validator = body(fieldName);

    if (!required) {
      validator = validator.optional();
    } else {
      validator = validator.notEmpty().withMessage(`${fieldName} is required`);
    }

    validator = validator
      .isString()
      .withMessage(`${fieldName} must be a string`)
      .isLength({
        min: minLength,
        max: maxLength
      })
      .withMessage(`${fieldName} must be between ${minLength} and ${maxLength} characters`);

    if (trim) {
      validator = validator.trim();
    }

    if (pattern) {
      validator = validator.matches(pattern).withMessage(message);
    }

    return [validator, this.handleValidationErrors];
  }

  /**
   * Validate numeric fields
   */
  static validateNumber(fieldName, options = {}) {
    const {
      required = true,
      min = undefined,
      max = undefined,
      isInt = false,
      message = `Invalid ${fieldName}`
    } = options;

    let validator = body(fieldName);

    if (!required) {
      validator = validator.optional();
    }

    if (isInt) {
      validator = validator.isInt({ min, max }).withMessage(message);
    } else {
      validator = validator.isFloat({ min, max }).withMessage(message);
    }

    return [validator, this.handleValidationErrors];
  }

  /**
   * Validate boolean fields
   */
  static validateBoolean(fieldName = 'isActive') {
    return [
      body(fieldName)
        .optional()
        .isBoolean()
        .withMessage(`${fieldName} must be true or false`),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate date fields
   */
  static validateDate(fieldName, options = {}) {
    const {
      required = true,
      isISO8601 = true,
      minDate = null,
      maxDate = null
    } = options;

    let validator = body(fieldName);

    if (!required) {
      validator = validator.optional();
    }

    if (isISO8601) {
      validator = validator.isISO8601().withMessage(`${fieldName} must be a valid ISO 8601 date`);
    } else {
      validator = validator.isDate().withMessage(`${fieldName} must be a valid date`);
    }

    if (minDate) {
      validator = validator.custom((value) => {
        const date = new Date(value);
        const min = new Date(minDate);
        if (date < min) {
          throw new Error(`${fieldName} must be after ${minDate}`);
        }
        return true;
      });
    }

    if (maxDate) {
      validator = validator.custom((value) => {
        const date = new Date(value);
        const max = new Date(maxDate);
        if (date > max) {
          throw new Error(`${fieldName} must be before ${maxDate}`);
        }
        return true;
      });
    }

    return [validator, this.handleValidationErrors];
  }

  /**
   * Validate URL fields
   */
  static validateUrl(fieldName = 'url') {
    return [
      body(fieldName)
        .optional()
        .isURL({
          protocols: ['http', 'https'],
          require_protocol: true
        })
        .withMessage(`${fieldName} must be a valid HTTP/HTTPS URL`),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate file uploads (checks presence only - actual validation in multer)
   */
  static validateFile(fieldName = 'file', options = {}) {
    const { required = true } = options;

    return [(req, res, next) => {
      if (required && !req.file && !req.files) {
        return res.status(400).json({
          success: false,
          message: `${fieldName} is required`
        });
      }
      next();
    }];
  }

  /**
   * Sanitize HTML to prevent XSS
   */
  static sanitizeHtml(fieldName) {
    return [
      body(fieldName)
        .optional()
        .escape()
        .withMessage(`${fieldName} contains invalid characters`),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate pagination parameters
   */
  static validatePagination() {
    return [
      query('page')
        .optional()
        .isInt({ min: 1 })
        .toInt()
        .withMessage('Page must be a positive integer'),
      query('limit')
        .optional()
        .isInt({ min: 1, max: 100 })
        .toInt()
        .withMessage('Limit must be between 1 and 100'),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate sorting parameters
   */
  static validateSorting(allowedFields = []) {
    return [
      query('sortBy')
        .optional()
        .isString()
        .trim(),
      query('order')
        .optional()
        .isIn(['asc', 'desc'])
        .withMessage('Order must be asc or desc'),
      (req, res, next) => {
        if (req.query.sortBy && allowedFields.length > 0) {
          if (!allowedFields.includes(req.query.sortBy)) {
            return res.status(400).json({
              success: false,
              message: `Invalid sort field. Allowed: ${allowedFields.join(', ')}`
            });
          }
        }
        next();
      }
    ];
  }

  /**
   * Validate currency codes
   */
  static validateCurrency(fieldName = 'currency') {
    return [
      body(fieldName)
        .optional()
        .isIn(['USD', 'EUR', 'GBP', 'NGN', 'FIC'])
        .withMessage('Invalid currency code'),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate status fields with allowed values
   */
  static validateStatus(fieldName = 'status', allowedValues = []) {
    return [
      body(fieldName)
        .optional()
        .isIn(allowedValues)
        .withMessage(`Invalid status. Allowed: ${allowedValues.join(', ')}`),
      this.handleValidationErrors
    ];
  }

  /**
   * Create composite validation for multiple fields
   */
  static createValidation(rules = []) {
    return [...rules, this.handleValidationErrors];
  }

  /**
   * Validate JSON object structure
   */
  static validateJsonObject(fieldName = 'metadata') {
    return [
      body(fieldName)
        .optional()
        .isObject()
        .withMessage(`${fieldName} must be a valid JSON object`),
      this.handleValidationErrors
    ];
  }

  /**
   * Validate array fields
   */
  static validateArray(fieldName, options = {}) {
    const {
      required = true,
      minLength = 0,
      maxLength = 100,
      itemType = 'string'
    } = options;

    let validator = body(fieldName);

    if (!required) {
      validator = validator.optional();
    }

    validator = validator
      .isArray({
        min: minLength,
        max: maxLength
      }).withMessage(`${fieldName} must be an array`);

    if (itemType === 'string') {
      validator = validator.custom((arr) => {
        if (arr.some(item => typeof item !== 'string')) {
          throw new Error(`All items in ${fieldName} must be strings`);
        }
        return true;
      });
    } else if (itemType === 'number') {
      validator = validator.custom((arr) => {
        if (arr.some(item => typeof item !== 'number')) {
          throw new Error(`All items in ${fieldName} must be numbers`);
        }
        return true;
      });
    }

    return [validator, this.handleValidationErrors];
  }
}

module.exports = InputValidationMiddleware;

/**
 * NexusGNN Middleware
 * Rate limiting, validation, and caching for NexusGNN endpoints
 *,
Date: June 12, 2026
