const rateLimit = require('express-rate-limit');
const logger = require('../utils/logger');
const { RATE_LIMITS, CACHE_CONFIG } = require('../constants/nexusgnn');

/**
 * Rate limiter for find matches endpoint
 */
const findMatchesLimiter = rateLimit({
  windowMs: RATE_LIMITS.FIND_MATCHES.WINDOW_MS,
  max: RATE_LIMITS.FIND_MATCHES.MAX_REQUESTS,
  message: {
    success: false,
    message: 'Too many match requests. Please try again later.',
    retryAfter: Math.ceil(RATE_LIMITS.FIND_MATCHES.WINDOW_MS / 1000)
  },
  standardHeaders: true,
  keyGenerator: (req) => req.user?.id || req.ip
});

/**
 * Rate limiter for recommendations endpoint
 */
const recommendationsLimiter = rateLimit({
  windowMs: RATE_LIMITS.GET_RECOMMENDATIONS.WINDOW_MS,
  max: RATE_LIMITS.GET_RECOMMENDATIONS.MAX_REQUESTS,
  message: {
    success: false,
    message: 'Too many recommendation requests. Please try again later.',
    retryAfter: Math.ceil(RATE_LIMITS.GET_RECOMMENDATIONS.WINDOW_MS / 1000)
  },
  standardHeaders: true,
  keyGenerator: (req) => req.user?.id || req.ip
});

/**
 * Rate limiter for lifecycle updates
 */
const lifecycleUpdateLimiter = rateLimit({
  windowMs: RATE_LIMITS.UPDATE_LIFECYCLE.WINDOW_MS,
  max: RATE_LIMITS.UPDATE_LIFECYCLE.MAX_REQUESTS,
  message: {
    success: false,
    message: 'Too many lifecycle update requests. Please try again later.',
    retryAfter: Math.ceil(RATE_LIMITS.UPDATE_LIFECYCLE.WINDOW_MS / 1000)
  },
  standardHeaders: true,
  keyGenerator: (req) => req.user?.id || req.ip
});

/**
 * Validate match request body
 */
const validateMatchRequest = (req, res, next) => {
  const { contentType, limit, options } = req.body;

  // Validate limit
  if (limit && (typeof limit !== 'number' || limit < 1 || limit > 100)) {
    return res.status(400).json({
      success: false,
      message: 'Limit must be a number between 1 and 100'
    });
  }

  // Validate contentType if provided
  if (contentType && typeof contentType !== 'string') {
    return res.status(400).json({
      success: false,
      message: 'Content type must be a string'
    });
  }

  next();
};

/**
 * Validate content lifecycle update request
 */
const validateLifecycleUpdate = (req, res, next) => {
  const { metrics } = req.body;

  if (!metrics || typeof metrics !== 'object') {
    return res.status(400).json({
      success: false,
      message: 'Metrics object is required'
    });
  }

  // Validate required metric fields
  const requiredFields = ['impressions', 'saves', 'shares'];
  const missingFields = requiredFields.filter(field =>
    metrics[field] === undefined || typeof metrics[field] !== 'number'
  );

  if (missingFields.length > 0) {
    return res.status(400).json({
      success: false,
      message: `Missing required metric,
fields: ${missingFields.join(', ')}`
    });
  }

  next();
};

/**
 * Cache middleware for match scores
 * Simple in-memory cache (use Redis in production)
 */
const matchScoreCache = new Map();

const cacheMatchScore = (req, res, next) => {
  const { userId, contentId } = req.params;
  const cacheKey = `${userId}:${contentId}`;

  const cached = matchScoreCache.get(cacheKey);

  if (cached && Date.now() - cached.timestamp < CACHE_CONFIG.MATCH_SCORE_TTL_SECONDS * 1000) {
    return res.json({
      success: true,
      message: 'Match score retrieved from cache',
      data: cached.score,
      cached: true,
      timestamp: new Date().toISOString()
    });
  }

  // Store original json method to intercept response
  const originalJson = res.json.bind(res);

  res.json = (data) => {
    if (data.success && data.data?.score) {
      matchScoreCache.set(cacheKey, {
        score: data.data.score,
        timestamp: Date.now()
      });
    }
    return originalJson(data);
  };

  next();
};

/**
 * Clean expired cache entries (run periodically)
 */
const cleanExpiredCache = () => {
  const now = Date.now();
  for (const [key, value] of matchScoreCache.entries()) {
    if (now - value.timestamp > CACHE_CONFIG.MATCH_SCORE_TTL_SECONDS * 1000) {
      matchScoreCache.delete(key);
    }
  }
};

// Run cache cleanup every 5 minutes
setInterval(cleanExpiredCache, 5 * 60 * 1000);

/**
 * Log NexusGNN API usage for analytics
 */
const logNexusGNNUsage = (req, res, next) => {
  const startTime = Date.now();

  // Intercept response to log after completion
  const originalEnd = res.end.bind(res);

  res.end = (...args) => {
    const duration = Date.now() - startTime;

    logger.info('[NexusGNN Analytics]', {
      endpoint: req.originalUrl,
      method: req.method,
      userId: req.user?.id,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      timestamp: new Date().toISOString()
    });

    originalEnd(...args);
  };

  next();
};

module.exports = {
  findMatchesLimiter,
  recommendationsLimiter,
  lifecycleUpdateLimiter,
  validateMatchRequest,
  validateLifecycleUpdate,
  cacheMatchScore,
  logNexusGNNUsage
};

/**
 * RequestLoggerMiddleware
 * Comprehensive request/response logging with performance tracking
 */

const morgan = require('morgan');
const logger = require('../utils/logger');
const fs = require('fs');
const path = require('path');

// Ensure logs directory exists
const logDir = path.join(__dirname, '../logs');
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir, {
    recursive: true });
}

// Create write streams for different log levels
const accessLogStream = fs.createWriteStream(
  path.join(logDir, 'access.log'),
  {
    flags: 'a' }
);

const errorLogStream = fs.createWriteStream(
  path.join(logDir, 'error.log'),
  {
    flags: 'a' }
);

const performanceLogStream = fs.createWriteStream(
  path.join(logDir, 'performance.log'),
  {
    flags: 'a' }
);

// Custom Morgan format for detailed logging
const detailedFormat = ':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent" :response-time ms';

// Request logger middleware
const requestLogger = (req, res, next) => {
  const start = Date.now();
  const requestId = req.headers['x-request-id'] || generateRequestId();

  // Add request ID to response headers
  res.setHeader('X-Request-ID', requestId);
  req.requestId = requestId;

  // Log request start
  logger.info(`[${requestId}] ${req.method} ${req.originalUrl} from ${req.ip}`);

  // Capture response finish
  res.on('finish', () => {
    const duration = Date.now() - start;
    const logEntry = {
      timestamp: new Date().toISOString(),
      requestId,
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
      userId: req.user?.id || 'anonymous'
    };

    // Write to performance log
    performanceLogStream.write(JSON.stringify(logEntry) + '\n');

    // Log slow requests
    if (duration > 1000) {
      logger.warn(`[${requestId}] SLOW REQUEST: ${duration}ms - ${req.method} ${req.originalUrl}`);
    }
  });

  next();
};

// Error logger middleware
const errorLogger = (err, req, res, next) => {
  const errorEntry = {
    timestamp: new Date().toISOString(),
    requestId: req.requestId,
    method: req.method,
    url: req.originalUrl,
    error: err.message,
    stack: err.stack,
    userId: req.user?.id || 'anonymous',
    ip: req.ip
  };

  errorLogStream.write(JSON.stringify(errorEntry) + '\n');
  logger.error(`[ERROR] ${req.requestId}: ${err.message}`);

  next(err);
};

// Helper function to generate unique request IDs
function generateRequestId() {
  return `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

module.exports = {
  requestLogger,
  errorLogger,
  detailedFormat,
  accessLogStream,
  performanceLogStream
};

/**
 * SecurityHeadersMiddleware
 * Comprehensive security headers using helmet.js patterns
 */

const helmet = require('helmet');

// Custom security headers configuration
const securityHeaders = (req, res, next) => {
  // Strict Transport Security
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // XSS Protection
  res.setHeader('X-XSS-Protection', '0'); // Deprecated but still used

  // Referrer Policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Permissions Policy (formerly Feature-Policy)
  res.setHeader('Permissions-Policy',
    'camera=(), microphone=(), geolocation=(), payment=(), usb=()'
  );

  // Content Security Policy
  res.setHeader('Content-Security-Policy',
    'default-src \'self\'; ' +
    'script-src \'self\' \'unsafe-inline\' \'unsafe-eval\'; ' +
    'style-src \'self\' \'unsafe-inline\'; ' +
    'img-src \'self\' data: https:; ' +
    'font-src \'self\'; ' +
    'connect-src \'self\' https:; ' +
    'frame-ancestors \'none\'; ' +
    'base-uri \'self\'; ' +
    'form-action \'self\''
  );

  // Cross-Origin policies
  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
  res.setHeader('Cross-Origin-Embedder-Policy', 'require-corp');

  // Cache Control for sensitive endpoints
  if (req.path.includes('/api/')) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
  }

  // Remove server header
  res.removeHeader('X-Powered-By');

  next();
};

module.exports = securityHeaders;

// Sentinel Control Middleware for FingerMobile P2P Matching System

const db = require('../db');
const logger = require('../utils/logger');

// Sentinel control types
const SentinelControlTypes = {
  MATCHING_RULE: 'matching_rule',
  FRAUD_DETECTION: 'fraud_detection',
  PRIVACY_CONTROL: 'privacy_control',
  ACCESS_CONTROL: 'access_control',
  COMPLIANCE_CHECK: 'compliance_check'
};

// Sentinel severity levels
const SeverityLevels = {
  LOW: 'low',
  MEDIUM: 'medium',
  HIGH: 'high',
  CRITICAL: 'critical'
};

// Sentinel control middleware
const sentinelControl = async (req, res, next) => {
  try {
    // Get all active sentinel controls
    const activeControls = await db.query(
      'SELECT * FROM fm_sentinel_controls WHERE is_active = true ORDER BY priority_level DESC'
    );

    if (activeControls.rows.length === 0) {
      // No sentinel controls active, proceed normally
      return next();
    }

    // Process each active control
    for (const control of activeControls.rows) {
      const result = await processSentinelControl(control, req, res);

      if (!result.allowed) {
        // Log the violation
        await db.query(
          `INSERT INTO fm_sentinel_logs (
                        log_type, severity, entity_id, entity_type, 
                        action_taken, details
                    ) VALUES ($1, $2, $3, $4, $5, $6)`,
          [
            'policy_violation',
            control.config_params?.default_severity || 'medium',
            req.member?.id || null,
            req.member ? 'member' : 'request',
            'blocked',
            {
              control_id: control.id,
              control_name: control.control_name,
              violation_details: result.reason,
              request_path: req.path,
              request_method: req.method
            }
          ]
        );

        return res.status(403).json({
          error: 'Access denied by Sentinel control',
          reason: result.reason
        });
      }
    }

    // Log successful access
    await db.query(
      `INSERT INTO fm_sentinel_logs (
                log_type, severity, entity_id, entity_type, 
                action_taken, details
            ) VALUES ($1, $2, $3, $4, $5, $6)`,
      [
        'access_granted',
        'info',
        req.member?.id || null,
        req.member ? 'member' : 'request',
        'allowed',
        {
          request_path: req.path,
          request_method: req.method,
          timestamp: new Date().toISOString()
        }
      ]
    );

    next();
  } catch (error) {
    logger.error('Sentinel control error:', error.message);
    return res.status(500).json({
      error: 'Sentinel control system error' });
  }
};

// Process individual sentinel control
const processSentinelControl = async (control, req, res) => {
  switch (control.control_type) {
  case SentinelControlTypes.MATCHING_RULE:
    return processMatchingRule(control, req, res);
  case SentinelControlTypes.FRAUD_DETECTION:
    return processFraudDetection(control, req, res);
  case SentinelControlTypes.PRIVACY_CONTROL:
    return processPrivacyControl(control, req, res);
  case SentinelControlTypes.ACCESS_CONTROL:
    return processAccessControl(control, req, res);
  case SentinelControlTypes.COMPLIANCE_CHECK:
    return processComplianceCheck(control, req, res);
  default:
    return {
      allowed: true };
  }
};

// Process matching rule control
const processMatchingRule = async (control, req, res) => {
  const config = control.config_params || {};

  // Example: Limit number of matches per member per day
  if (config.limit_matches_per_day) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const matchesToday = await db.query(
      `SELECT COUNT(*) as count FROM fm_p2p_matches 
            WHERE sent_by_member_id = $1 AND created_at >= $2`,
      [req.member?.id || null, today]
    );

    if (parseInt(matchesToday.rows[0].count) >= config.max_matches_per_day) {
      return {
        allowed: false,
        reason: `Maximum daily matches limit (${config.max_matches_per_day}) reached`
      };
    }
  }

  return {
    allowed: true };
};

// Process fraud detection control
const processFraudDetection = async (control, req, res) => {
  const config = control.config_params || {};

  // Check for AI insights with high fraud risk
  if (req.member?.id) {
    const fraudInsights = await db.query(
      `SELECT * FROM fm_ai_insights 
            WHERE entity_id = $1 AND insight_type = 'fraud_risk' 
            AND severity_level IN ('high', 'critical') AND is_flagged = true`,
      [req.member.id]
    );

    if (fraudInsights.rows.length > 0) {
      return {
        allowed: false,
        reason: 'Member flagged for high fraud risk'
      };
    }
  }

  return {
    allowed: true };
};

// Process privacy control
const processPrivacyControl = async (control, req, res) => {
  const config = control.config_params || {};

  // Example: Check if member has access to profile analysis
  if (req.path.includes('/profile-analysis') && req.query.analyzermemberId) {
    if (!req.member || req.query.analyzermemberId !== req.member.id) {
      return {
        allowed: false,
        reason: 'Unauthorized access to profile analysis'
      };
    }

    // Check FIC subscription
    const subscription = await db.query(
      `SELECT * FROM fm_fic_subscriptions 
            WHERE member_id = $1 AND is_active = true`,
      [req.member.id]
    );

    if (subscription.rows.length === 0) {
      return {
        allowed: false,
        reason: 'FIC subscription required for profile analysis'
      };
    }
  }

  return {
    allowed: true };
};

// Process access control
const processAccessControl = async (control, req, res) => {
  const config = control.config_params || {};

  // Example: Restrict access based on IP or other factors
  if (config.restricted_ips && req.ip) {
    if (config.restricted_ips.includes(req.ip)) {
      return {
        allowed: false,
        reason: 'IP address restricted'
      };
    }
  }

  return {
    allowed: true };
};

// Process compliance check
const processComplianceCheck = async (control, req, res) => {
  const config = control.config_params || {};

  // Example: Check if required fields are provided for procurement
  if (req.path.includes('/procurement-documents') && req.method === 'POST') {
    const requiredFields = config.required_fields || [];
    for (const field of requiredFields) {
      if (!req.body[field]) {
        return {
          allowed: false,
          reason: `Missing required,
field: ${field}`
        };
      }
    }
  }

  return {
    allowed: true };
};

// Specialized middleware for specific P2P match creation
const sentinelP2PMatchControl = async (req, res, next) => {
  try {
    // Get active matching rules
    const matchingRules = await db.query(
      `SELECT * FROM fm_sentinel_controls 
            WHERE control_type = 'matching_rule' AND is_active = true 
            ORDER BY priority_level DESC`
    );

    for (const rule of matchingRules.rows) {
      const result = await evaluateMatchRule(rule, req.body);

      if (!result.allowed) {
        await db.query(
          `INSERT INTO fm_sentinel_logs (
                        log_type, severity, entity_id, entity_type, 
                        action_taken, details
                    ) VALUES ($1, $2, $3, $4, $5, $6)`,
          [
            'match_violation',
            rule.config_params?.default_severity || 'medium',
            req.member?.id || null,
            'member',
            'blocked',
            {
              rule_id: rule.id,
              rule_name: rule.control_name,
              violation_details: result.reason,
              match_attempt: req.body
            }
          ]
        );

        return res.status(403).json({
          error: 'Match creation blocked by Sentinel control',
          reason: result.reason
        });
      }
    }

    next();
  } catch (error) {
    logger.error('Sentinel P2P match control error:', error.message);
    return res.status(500).json({
      error: 'Sentinel control system error' });
  }
};

// Evaluate a specific match rule
const evaluateMatchRule = async (rule, matchData) => {
  const config = rule.config_params || {};

  // Example: Prevent matches between members with significant age difference
  if (config.age_difference_limit) {
    const member1Profile = await db.query(
      'SELECT age FROM fm_member_profiles WHERE member_id = $1',
      [matchData.member1_id]
    );

    const member2Profile = await db.query(
      'SELECT age FROM fm_member_profiles WHERE member_id = $1',
      [matchData.member2_id]
    );

    if (member1Profile.rows[0] && member2Profile.rows[0]) {
      const ageDiff = Math.abs(member1Profile.rows[0].age - member2Profile.rows[0].age);
      if (ageDiff > config.age_difference_limit) {
        return {
          allowed: false,
          reason: `Age difference exceeds limit of ${config.age_difference_limit} years`
        };
      }
    }
  }

  // Example: Check for fraud flags on either member
  const fraudCheck1 = await db.query(
    `SELECT COUNT(*) as count FROM fm_ai_insights 
        WHERE entity_id = $1 AND insight_type = 'fraud_risk' 
        AND severity_level IN ('high', 'critical') AND is_flagged = true`,
    [matchData.member1_id]
  );

  const fraudCheck2 = await db.query(
    `SELECT COUNT(*) as count FROM fm_ai_insights 
        WHERE entity_id = $1 AND insight_type = 'fraud_risk' 
        AND severity_level IN ('high', 'critical') AND is_flagged = true`,
    [matchData.member2_id]
  );

  if (parseInt(fraudCheck1.rows[0].count) > 0 || parseInt(fraudCheck2.rows[0].count) > 0) {
    return {
      allowed: false,
      reason: 'One or both members flagged for fraud risk'
    };
  }

  return {
    allowed: true };
};

module.exports = {
  sentinelControl,
  sentinelP2PMatchControl,
  SentinelControlTypes,
  SeverityLevels
};

/**
 * STERCS Integration Middleware for FingerMobile Platform
 * Sends session tracking data to STERCS standalone service
 *
 * Installation: Add this middleware to apps/backend/middleware/stercsTracker.js
 */

const axios = require('axios');
const logger = require('../utils/logger'); // Adjust path as needed

// STERCS API Configuration
const STERCS_API_URL = process.env.STERCS_API_URL || 'http://stercs-backend:3022';
const STERCS_API_KEY = process.env.STERCS_API_KEY || 'your_api_key_here';

// Module name mapping
const MODULE_MAP = {
  '/api/photocredits': 'PhotoCredits',
  '/api/storefront': 'Storefront',
  '/api/fingerwars': 'FingerWars',
  '/api/wallet': 'Wallet',
  '/api/fingerlux': 'FingerLux',
  '/api/forum': 'Forum',
  '/api/flamingo': 'Flamingo',
  '/api/trends': 'Trends',
  '/api/beatwaveng': 'BeatwaveNG',
  '/api/imperial-builder': 'ImperialBuilder',
  '/api/gems': 'Gems',
};

/**
 * Extract module name from request path
 */
function extractModuleName(req) {
  const pathParts = req.path.split('/').filter(p => p);

  for (const [path, moduleName] of Object.entries(MODULE_MAP)) {
    if (req.path.startsWith(path)) {
      return moduleName;
    }
  }

  return 'Unknown';
}

/**
 * Determine action type from HTTP method and path
 */
function determineAction(method, path) {
  const methodActions = {
    GET: 'read',
    POST: 'create',
    PUT: 'update',
    PATCH: 'update',
    DELETE: 'delete',
  };

  return methodActions[method] || 'unknown';
}

/**
 * STERCS Session Tracking Middleware
 * Tracks all authenticated requests and sends to STERCS service
 * Fire-and-forget pattern - never blocks main request flow
 */
async function trackSessionToSTERCS(req, res, next) {
  try {
    // Only track authenticated users
    if (!req.user?.id) {
      return next();
    }

    // Don't track health checks or static assets
    if (req.path.startsWith('/health') || req.path.includes('.')) {
      return next();
    }

    const moduleName = extractModuleName(req);
    const actionType = determineAction(req.method, req.path);

    // Prepare session data
    const sessionData = {
      userId: req.user.id,
      username: req.user.username || req.user.email || 'unknown',
      moduleName,
      sessionId: req.sessionID || req.headers['x-session-id'],
      actionType,
      ipAddress: req.ip || req.connection.remoteAddress,
      userAgent: req.get('User-Agent'),
      requestPath: req.originalUrl,
      requestMethod: req.method,
      statusCode: null, // Will be set after response
      responseTimeMs: null, // Will be set after response
      metadata: {
        query_params: Object.keys(req.query).length > 0 ? req.query : undefined,
        body_keys: req.body && Object.keys(req.body).length > 0 ? Object.keys(req.body) : undefined,
      },
    };

    // Capture response time and status code
    const startTime = Date.now();

    // Hook into response finish event
    res.on('finish', () => {
      sessionData.statusCode = res.statusCode;
      sessionData.responseTimeMs = Date.now() - startTime;

      // Send to STERCS (fire-and-forget)
      sendToSTERCS(sessionData).catch(err => {
        logger.error('Failed to send session data to STERCS:', err.message);
      });
    });

    next();
  } catch (error) {
    // Never block main flow - log error and continue
    logger.error('Error in STERCS tracking middleware:', error);
    next();
  }
}

/**
 * Send session data to STERCS API
 */
async function sendToSTERCS(sessionData) {
  try {
    const response = await axios.post(
      `${STERCS_API_URL}/api/session-traces/track`,
      sessionData,
      {
        headers: {
          'X-API-Key': STERCS_API_KEY,
          'Content-Type': 'application/json',
        },
        timeout: 1000, // 1 second timeout - don't wait long
      }
    );

    logger.debug(`Session tracked to STERCS: ${sessionData.userId} -> ${sessionData.moduleName}`);
    return response.data;
  } catch (error) {
    // Log but don't throw - this is fire-and-forget
    if (error.code === 'ECONNABORTED') {
      logger.warn('STERCS tracking timeout (non-critical)');
    } else {
      logger.error('STERCS tracking failed:', error.message);
    }
    return null;
  }
}

/**
 * Webhook handler for receiving STERCS alerts
 * Mount this route in your main app: app.use('/webhooks/stercs', stercsWebhookHandler)
 */
function stercsWebhookHandler(req, res) {
  try {
    const { eventType, severity, details, timestamp } = req.body;

    // Verify webhook signature if configured
    const signature = req.headers['x-webhook-signature'];
    if (signature && !verifyWebhookSignature(req.body, signature)) {
      logger.warn('Invalid webhook signature received');
      return res.status(401).json({ success: false, message: 'Invalid signature' });
    }

    // Handle different event types
    switch (eventType) {
    case 'critical_security_alert':
      handleCriticalSecurityAlert(details);
      break;
    case 'lockdown_triggered':
      handleLockdownTriggered(details);
      break;
    case 'compliance_report_ready':
      handleComplianceReportReady(details);
      break;
    case 'violation_threshold_exceeded':
      handleViolationThreshold(details);
      break;
    case 'injection_attempt_blocked':
      handleInjectionAttempt(details);
      break;
    default:
      logger.info(`Received STERCS webhook: ${eventType}`);
    }

    res.json({ success: true, received: true });
  } catch (error) {
    logger.error('Error handling STERCS webhook:', error);
    res.status(500).json({ success: false, error: error.message });
  }
}

/**
 * Verify webhook signature (HMAC-SHA256)
 */
function verifyWebhookSignature(payload, signature) {
  const crypto = require('crypto');
  const secret = process.env.STERCS_WEBHOOK_SECRET || 'webhook_secret_2026';

  const expectedSignature = crypto
    .createHmac('sha256', secret)
    .update(JSON.stringify(payload))
    .digest('hex');

  return signature === expectedSignature;
}

/**
 * Event handlers for STERCS webhooks
 */
function handleCriticalSecurityAlert(details) {
  logger.critical('CRITICAL SECURITY ALERT from STERCS:', details);
  // TODO: Send to PagerDuty, Slack, email, etc.
}

function handleLockdownTriggered(details) {
  logger.warn('LOCKDOWN TRIGGERED by STERCS:', details);
  // TODO: Activate platform-wide lockdown mechanisms
}

function handleComplianceReportReady(details) {
  logger.info('Compliance report ready:', details);
  // TODO: Notify compliance team, store report
}

function handleViolationThreshold(details) {
  logger.warn('Violation threshold exceeded:', details);
  // TODO: Alert security team, consider account suspension
}

function handleInjectionAttempt(details) {
  logger.warn('Injection attempt detected:', details);
  // TODO: Block IP, alert security team
}

module.exports = {
  trackSessionToSTERCS,
  stercsWebhookHandler,
};

