router.get('/unified-products', async (req, res) => {
  try {
    const { platform = 'all', limit = 50, offset = 0 } = req.query;

    let query = `
      SELECT p.id, p.name, p.description, p.price, p.is_active as status, 
             u.username as seller_name, u.email as seller_full_name,
             0 as avg_rating,
             0 as review_count,
             p.stock_quantity,
             p.images[1] as image_url,
             p.platform_type,
             p.created_at
      FROM products p
      JOIN users u ON p.creator_id = u.id
      WHERE p.is_active = true
    `;

    // Add platform filtering if not 'all'
    if (platform !== 'all') {
      query += ' AND p.platform_type = $3';
    }

    query += ' ORDER BY p.created_at DESC LIMIT $1 OFFSET $2';

    const queryParams = [parseInt(limit), parseInt(offset)];
    if (platform !== 'all') {
      queryParams.push(platform);
    }

    const result = await identityDb.query(query, queryParams);

    res.json({
      success: true,
      data: result.rows,
      pagination: {
        limit: parseInt(limit),
        offset: parseInt(offset),
        total: result.rows.length // In real implementation, you'd get the total count separately
      }
    });
  } catch (error) {
    logger.error('Error fetching unified products:', error);
    res.status(500).json({
      success: false,
      message: 'Failed to fetch products'
    });
  }
});

// Get all products with filtering and pagination
router.get('/products', async (req, res) => {
  try {
    const {
      category,
      min_price,
      max_price,
      search,
      sort = 'created_at',
      order = 'DESC',
      limit = 50,
      offset = 0
    } = req.query;

    let query = `
      SELECT p.*, m.name as seller_name, m.membername as seller_username,
             COALESCE(AVG(pr.rating), 0) as avg_rating,
             COUNT(pr.id) as review_count
      FROM products p
      LEFT JOIN members m ON p.creator_id = m.id
      LEFT JOIN product_reviews pr ON p.id = pr.product_id
      WHERE p.is_active = true
    `;

    const params = [];
    let paramIndex = 1;

    if (category) {
      query += ` AND p.category = $${paramIndex++}`;
      params.push(category);
    }

    if (min_price) {
      query += ` AND p.price >= $${paramIndex++}`;
      params.push(parseFloat(min_price));
    }

    if (max_price) {
      query += ` AND p.price <= $${paramIndex++}`;
      params.push(parseFloat(max_price));
    }

    if (search) {
      query += ` AND (p.name ILIKE $${paramIndex} OR p.description ILIKE $${paramIndex})`;
      params.push(`%${search}%`);
      paramIndex++;
    }

    query += ' GROUP BY p.id, m.id';
    query += ` ORDER BY ${sort} ${order}`;
    query += ` LIMIT $${paramIndex++} OFFSET $${paramIndex++}`;
    params.push(parseInt(limit), parseInt(offset));

    const { rows } = await identityDb.query(query, params);

    // Get total count for pagination
    const countResult = await identityDb.query(
      'SELECT COUNT(*) FROM products WHERE is_active = true'
    );

    res.json({
      products: rows,
      total: parseInt(countResult.rows[0].count),
      page: Math.floor(offset / limit) + 1,
      limit: parseInt(limit)
    });
  } catch (error) {
    console.error('Error fetching products:', error);
    res.status(500).json({ error: 'Failed to fetch products' });
  }
});

// Get single product by ID with reviews
router.get('/products/:id', async (req, res) => {
  try {
    const { id } = req.params;

    const product = await identityDb.query(
      `SELECT p.*, m.name as seller_name, m.membername as seller_username,
              COALESCE(AVG(pr.rating), 0) as avg_rating,
              COUNT(pr.id) as review_count
       FROM products p
       LEFT JOIN members m ON p.creator_id = m.id
       LEFT JOIN product_reviews pr ON p.id = pr.product_id
       WHERE p.id = $1
       GROUP BY p.id, m.id`,
      [id]
    );

    if (product.rows.length === 0) {
      return res.status(404).json({ error: 'Product not found' });
    }

    // Get reviews
    const reviews = await identityDb.query(
      `SELECT pr.*, m.name as reviewer_name, m.membername as reviewer_username
       FROM product_reviews pr
       LEFT JOIN members m ON pr.member_id = m.id
       WHERE pr.product_id = $1
       ORDER BY pr.created_at DESC`,
      [id]
    );

    res.json({ ...product.rows[0], reviews: reviews.rows });
  } catch (error) {
    console.error('Error fetching product:', error);
    res.status(500).json({ error: 'Failed to fetch product' });
  }
});

