router.put('/products/:id', authenticate, async (req, res) => {
  try {
    const { id } = req.params;
    const creatorId = req.member.id;

    // Verify ownership
    const existing = await identityDb.query(
      'SELECT creator_id FROM products WHERE id = $1',
      [id]
