#!/usr/bin/env node
/**
 * COMPREHENSIVE PLATFORM AUDIT SCRIPT
 * Finds ALL stubs, missing components, broken dependencies, and incomplete implementations
 *,
Date: June 14, 2026
 */

const fs = require('fs');
const path = require('path');

const BACKEND_DIR = path.join(__dirname);
const RESULTS = {stubs: [],
  missingModels: [],
  missingControllers: [],
  missingServices: [],
  typescriptErrors: [],
  brokenImports: [],
  unregisteredRoutes: [],
  incompleteMethods: [],
  missingTests: []
};

// Helper functions
function readFilesRecursively(dir, pattern) {
  let results = [];
  const files = fs.readdirSync(dir);

  files.forEach((file) => {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    if (stat.isDirectory() && !file.includes('node_modules') && !file.includes('.git')) {
      results = results.concat(readFilesRecursively(filePath, pattern));
    } else if (pattern.test(file)) {
      results.push(filePath);
    }
  });

  return results;
}

function findStubs() {
  logger.info('\n🔍 Finding stubs and incomplete implementations...');
  const controllers = readFilesRecursively(path.join(BACKEND_DIR, 'controllers'), /\.(js|ts)$/);
  const services = readFilesRecursively(path.join(BACKEND_DIR, 'services'), /\.(js|ts)$/);

  [...controllers, ...services].forEach((file) => {
    const content = fs.readFileSync(file, 'utf8');
    const relativePath = path.relative(BACKEND_DIR, file);

    // Check for various stub patterns
    const patterns = [
      {regex: /PLACEHOLDER/g,
  type: 'PLACEHOLDER' },
      {regex: /TODO.*implement/i,
  type: 'TODO' },
      {regex: /FIXME/i,
  type: 'FIXME' },
      {regex: /NOT IMPLEMENTED/i,
  type: 'NOT_IMPLEMENTED' },
      {regex: /STUB/i,
  type: 'STUB' },
      {regex: /throw new Error\(['"]not implemented['"]\)/i,
  type: 'NOT_IMPLEMENTED_ERROR' },
      {regex: /res\.status\(501\)/,
  type: '501_NOT_IMPLEMENTED' },
      {regex: /return null;/g,
  type: 'RETURNS_NULL' },
      {regex: /return undefined;/g,
  type: 'RETURNS_UNDEFINED' }
    ];

    patterns.forEach((pattern) => {
      const matches = content.match(pattern.regex);
      if (matches && matches.length > 0) {
        RESULTS.stubs.push({file: relativePath,
  type: pattern.type,
  count: matches.length
        });
      }
    });
  });

  logger.info(`   Found ${RESULTS.stubs.length} stub indicators`);
}

function findMissingModels() {
  logger.info('\n🔍 Finding missing model dependencies...');
  const existingModels = fs.readdirSync(path.join(BACKEND_DIR, 'models'))
    .map(f => f.replace(/\.[^.]+$/, ''));

  const controllers = readFilesRecursively(path.join(BACKEND_DIR, 'controllers'), /\.(js|ts)$/);
  const services = readFilesRecursively(path.join(BACKEND_DIR, 'services'), /\.(js|ts)$/);

  const requiredModels = new Set();

  [...controllers, ...services].forEach((file) => {
    const content = fs.readFileSync(file, 'utf8');
    const matches = content.match(/require\(['"]\.\.\/models\/[^'"]+['"]\)/g);

    if (matches) {
      matches.forEach((match) => {
        const modelName = match.match(/models\/([^'"]+)/)[1].replace(/\.[jt]s$/, '');
        requiredModels.add(modelName);
      });
    }
  });

  [...requiredModels].forEach((model) => {
    if (!existingModels.includes(model)) {
      RESULTS.missingModels.push(model);
    }
  });

  logger.info(`   Found ${RESULTS.missingModels.length} missing models`);
}

function findBrokenImports() {
  logger.info('\n🔍 Finding broken imports and missing dependencies...');
  const allFiles = readFilesRecursively(BACKEND_DIR, /\.(js|ts)$/);

  allFiles.forEach((file) => {
    const content = fs.readFileSync(file, 'utf8');
    const relativePath = path.relative(BACKEND_DIR, file);

    // Check for external dependencies
    const externalDeps = [
      '@aws-sdk/client-s3',
      '@elastic/elasticsearch',
      'stripe',
      'twilio'
    ];

    externalDeps.forEach((dep) => {
      if (content.includes(dep)) {
        try {
          require.resolve(dep);
        } catch (e) {
          RESULTS.brokenImports.push({file: relativePath,
  dependency: dep,
  error: e.code
          });
        }
      }
    });
  });

  logger.info(`   Found ${RESULTS.brokenImports.length} broken imports`);
}

function findUnregisteredRoutes() {
  logger.info('\n🔍 Finding unregistered routes...');
  const indexPath = path.join(BACKEND_DIR, 'routes', 'index.js');
  const indexContent = fs.readFileSync(indexPath, 'utf8');

  // Get all route files
  const routeFiles = fs.readdirSync(path.join(BACKEND_DIR, 'routes'))
    .filter(f => f.endsWith('.js') && f !== 'index.js');

  // Check which ones are registered
  routeFiles.forEach((routeFile) => {
    const routeName = routeFile.replace('.js', '');
    const isRegistered = indexContent.includes(`require('./${routeName}')`) || 
                        indexContent.includes(`require("./${routeName}")`);

    if (!isRegistered && !routeFile.includes('backup')) {
      RESULTS.unregisteredRoutes.push(routeFile);
    }
  });

  logger.info(`   Found ${RESULTS.unregisteredRoutes.length} unregistered routes`);
}

function findTypeScriptErrors() {
  logger.info('\n🔍 Checking TypeScript compilation errors...');
  const { execSync } = require('child_process');

  try {
    // ⚠️,
SECURITY: Safe usage - hardcoded command with no user input,
stdio: 'pipe' prevents shell injection
    const output = execSync('npx tsc --noEmit 2>&1', {cwd: BACKEND_DIR,
  encoding: 'utf8',
  stdio: 'pipe'
    });

    const lines = output.split('\n').filter(line => line.includes('error TS'));
    RESULTS.typescriptErrors = lines.map((line) => {
      const match = line.match(/^(.+)\((\d+),(\d+)\): error TS\d+: (.+)$/);
      if (match) {
        return {file: match[1],
  line: parseInt(match[2]),
  column: parseInt(match[3]),
  message: match[4]
        };
      }
      return null;
    }).filter(Boolean);

    logger.info(`   Found ${RESULTS.typescriptErrors.length} TypeScript errors`);
  } catch (error) {
    logger.info('   TypeScript check completed with errors');
  }
}

function findMissingTests() {
  logger.info('\n🔍 Finding missing test coverage...');
  const controllers = fs.readdirSync(path.join(BACKEND_DIR, 'controllers'))
    .filter(f => f.match(/Controller\.(js|ts)$/));

  const testDir = path.join(BACKEND_DIR, 'tests');
  let testFiles = [];

  if (fs.existsSync(testDir)) {
    testFiles = readFilesRecursively(testDir, /\.test\.(js|ts)$/);
  }

  const testedControllers = new Set();
  testFiles.forEach((testFile) => {
    const content = fs.readFileSync(testFile, 'utf8');
    const matches = content.match(/require\(['"]\.\.\/controllers\/[^'"]+['"]\)/g);
    if (matches) {
      matches.forEach((match) => {
        const controller = match.match(/controllers\/([^'"]+)/)[1];
        testedControllers.add(controller);
      });
    }
  });

  controllers.forEach((controller) => {
    if (!testedControllers.has(controller)) {
      RESULTS.missingTests.push(controller);
    }
  });

  logger.info(`   Found ${RESULTS.missingTests.length} controllers without tests`);
}

function generateReport() {
  logger.info('\n\n' + '='.repeat(80));
  logger.info('COMPREHENSIVE PLATFORM AUDIT REPORT');
  logger.info('='.repeat(80));

  logger.info('\n📊,
SUMMARY:');
  logger.info(`   Stubs/Incomplete,
Implementations: ${RESULTS.stubs.length}`);
  logger.info(`   Missing,
Models: ${RESULTS.missingModels.length}`);
  logger.info(`   Broken,
Imports: ${RESULTS.brokenImports.length}`);
  logger.info(`   Unregistered,
Routes: ${RESULTS.unregisteredRoutes.length}`);
  logger.info(`   TypeScript,
Errors: ${RESULTS.typescriptErrors.length}`);
  logger.info(`   Controllers Without,
Tests: ${RESULTS.missingTests.length}`);

  if (RESULTS.stubs.length > 0) {
    logger.info('\n❌ STUBS AND INCOMPLETE,
IMPLEMENTATIONS:');
    RESULTS.stubs.forEach((stub) => {
      logger.info(`   - ${stub.file}: ${stub.type} (${stub.count} occurrences)`);
    });
  }

  if (RESULTS.missingModels.length > 0) {
    logger.info('\n❌ MISSING,
MODELS:');
    RESULTS.missingModels.forEach((model) => {
      logger.info(`   - ${model}`);
    });
  }

  if (RESULTS.brokenImports.length > 0) {
    logger.info('\n❌ BROKEN,
IMPORTS:');
    RESULTS.brokenImports.forEach((imp) => {
      logger.info(`   - ${imp.file}: ${imp.dependency} (${imp.error})`);
    });
  }

  if (RESULTS.unregisteredRoutes.length > 0) {
    logger.info('\n❌ UNREGISTERED,
ROUTES:');
    RESULTS.unregisteredRoutes.forEach((route) => {
      logger.info(`   - ${route}`);
    });
  }

  if (RESULTS.typescriptErrors.length > 0) {
    logger.info('\n❌ TYPESCRIPT ERRORS (first 20):');
    RESULTS.typescriptErrors.slice(0, 20).forEach((err) => {
      logger.info(`   - ${err.file}:${err.line}:${err.column} - ${err.message}`);
    });
  }

  if (RESULTS.missingTests.length > 0) {
    logger.info('\n❌ CONTROLLERS WITHOUT TESTS (first 20):');
    RESULTS.missingTests.slice(0, 20).forEach((controller) => {
      logger.info(`   - ${controller}`);
    });
  }

  // Save to file
  const reportPath = path.join(BACKEND_DIR, 'COMPREHENSIVE_AUDIT_RESULTS.json');
  fs.writeFileSync(reportPath, JSON.stringify(RESULTS, null, 2));
  logger.info(`\n✅ Full report saved,
to: ${reportPath}`);

  logger.info('\n' + '='.repeat(80));
}

// Run audit
logger.info('Starting comprehensive platform audit...\n');
findStubs();
findMissingModels();
findBrokenImports();
findUnregisteredRoutes();
findTypeScriptErrors();
findMissingTests();
generateReport();

