];

logger.info(`📋 Found ${unregisteredRoutes.length} unregistered routes\n`);

// Check which routes are already imported
const missingImports = [];
const missingRegistrations = [];

unregisteredRoutes.forEach((routeName) => {
  const importPattern = new RegExp(`require\\(['"]\\.\\/${routeName}['"]\\)`);
  const registrationPattern = new RegExp(`router\\.use\\(['"]/.*?${routeName}.*?['"]`);

  const hasImport = importPattern.test(indexContent);
  const hasRegistration = registrationPattern.test(indexContent);

  if (!hasImport) {
    missingImports.push(routeName);
  }

  if (!hasRegistration) {
    missingRegistrations.push(routeName);
  }
});

logger.info(`❌ Missing,
imports: ${missingImports.length}`);
logger.info(`❌ Missing,
registrations: ${missingRegistrations.length}\n`);

if (missingImports.length === 0 && missingRegistrations.length === 0) {
  logger.info('✅ All routes are already registered!');
  process.exit(0);
}

// Add missing imports after existing route imports
if (missingImports.length > 0) {
  logger.info('🔧 Adding missing imports...\n');

  // Find the last route import line
  const importLines = indexContent.split('\n').filter(line => 
    line.includes('require(\'./') && line.includes('routes/')
  );

  const lastImportIndex = importLines.length > 0 
    ? indexContent.lastIndexOf(importLines[importLines.length - 1])
    : indexContent.indexOf('const express');

  // Generate import statements
  const newImports = missingImports.map((routeName) => {
    const varName = routeName.replace(/-/g, '') + 'Routes';
    return `const ${varName} = require('./${routeName}');`;
  }).join('\n');

  // Insert after last import
  const insertPosition = lastImportIndex + importLines[importLines.length - 1].length + 1;
  indexContent = indexContent.slice(0, insertPosition) + '\n' + newImports + indexContent.slice(insertPosition);

  logger.info(`   ✅ Added ${missingImports.length} import statements\n`);
}

// Add missing route registrations before module.exports
if (missingRegistrations.length > 0) {
  logger.info('🔧 Adding missing route registrations...\n');

  // Find module.exports line
  const exportsIndex = indexContent.lastIndexOf('module.exports');

  // Generate registration statements
  const newRegistrations = missingRegistrations.map((routeName) => {
    const varName = routeName.replace(/-/g, '') + 'Routes';
    const endpoint = '/' + routeName.replace(/_/g, '-');
    return `router.use('${endpoint}', authenticate, ${varName});`;
  }).join('\n');

  // Insert before module.exports
  const registrationBlock = '\n// Auto-registered routes (fixed by auto_register_missing_routes.js)\n' + newRegistrations + '\n';
  indexContent = indexContent.slice(0, exportsIndex) + registrationBlock + '\n' + indexContent.slice(exportsIndex);

  logger.info(`   ✅ Added ${missingRegistrations.length} route registrations\n`);
}

// Write updated index.js
fs.writeFileSync(indexPath, indexContent, 'utf-8');

logger.info('========================================');
logger.info('REGISTRATION COMPLETE');
logger.info('========================================\n');
logger.info(`✅ Total routes,
registered: ${unregisteredRoutes.length - missingRegistrations.length + missingRegistrations.length}`);
logger.info(`📝 Updated,
file: routes/index.js`);
logger.info('\n⚠️,
IMPORTANT: Test the application to ensure all routes work correctly\n');

