#!/usr/bin/env node

/**
 * Comprehensive Syntax Repair Script
 * Fixes systematic corruption patterns across entire backend codebase
 */

const fs = require('fs');
const path = require('path');

const BACKEND_DIR = path.join(__dirname, '..');

// All known corruption patterns
const FIXES = [
  // Pattern 1: {,\n  key: → { key:
  {
    pattern: /\{,\s*\n\s*([a-z_]+:)/gi,
    replacement: '{ $1',
    description: 'Object literal opening'
  },

  // Pattern 2: property: ' value' → property: 'value'
  {
    pattern: /([a-z_]+:\s*)',\s*\n\s*([^']*')/g,
    replacement: '$1$2',
    description: 'Broken string literals'
  },

  // Pattern 3: method() }; → method()\n      },
  {
    pattern: /(sinon\.stub\(\))\s*,\s*\n(\s+\};)/g,
    replacement: '$1\n$2',
    description: 'Semicolon after object methods'
  },

  // Pattern 4: logger.error('message failed:') → logger.error('message failed:')
  {
    pattern: /(logger\.(error|warn|info)\('[^']*),\s*\n\s*(failed:[^']*'\);)/g,
    replacement: '$1 $3',
    description: 'Broken logger strings'
  },

  // Pattern 5: // Note: → // Note:
  {
    pattern: /(\/\/),\s*\n(\s*[A-Z])/g,
    replacement: '$1 $2',
    description: 'Broken comments'
  },

  // Pattern 6: Buffer.from('data'); → Buffer.from('data'),
  {
    pattern: /(Buffer\.from\([^)]+)\);\s*\n/g,
    replacement: '$1) ',
    description: 'Buffer semicolons in objects'
  },

  // Pattern 7: size: 1024, // comment;\n → size: 1024, // comment\n
  {
    pattern: /(\/\/[^;]*);(\s*\n)/g,
    replacement: '$1$2',
    description: 'Comment semicolons'
  }
];

function fixFile(filePath) {
  try {
    let content = fs.readFileSync(filePath, 'utf8');
    const originalContent = content;
    let totalFixes = 0;

    FIXES.forEach((fix, index) => {
      const matches = content.match(fix.pattern);
      if (matches && matches.length > 0) {
        const beforeCount = matches.length;
        content = content.replace(fix.pattern, fix.replacement);
        const afterCount = (content.match(fix.pattern) || []).length;
        const fixed = beforeCount - afterCount;

        if (fixed > 0) {
          totalFixes += fixed;
        }
      }
    });

    if (content !== originalContent) {
      fs.writeFileSync(filePath, content, 'utf8');
      return totalFixes;
    }

    return 0;
  } catch (err) {
    console.error(`Error processing ${filePath}:`, err.message);
    return -1;
  }
}

function scanDirectory(dirPath, pattern) {
  const files = [];

  function traverse(currentPath) {
    const items = fs.readdirSync(currentPath);

    items.forEach(item => {
      const fullPath = path.join(currentPath, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !item.includes('node_modules') && !item.includes('.git')) {
        traverse(fullPath);
      } else if (stat.isFile() && pattern.test(item)) {
        files.push(fullPath);
      }
    });
  }

  traverse(dirPath);
  return files;
}

// Main execution
console.log('🔧 Starting Comprehensive Syntax Repair\n');

// Scan test files
const testFiles = scanDirectory(path.join(BACKEND_DIR, 'tests'), /\.test\.(js|ts)$/);
const dunderTestFiles = scanDirectory(path.join(BACKEND_DIR, '__tests__'), /\.test\.(js|ts)$/);
const middlewareFiles = scanDirectory(path.join(BACKEND_DIR, 'middleware'), /\.js$/);

const allFiles = [...testFiles, ...dunderTestFiles, ...middlewareFiles];

console.log(`Found ${allFiles.length} files to process:\n`);
console.log(`  - Test files: ${testFiles.length + dunderTestFiles.length}`);
console.log(`  - Middleware files: ${middlewareFiles.length}\n`);

let totalFixed = 0;
let filesWithErrors = 0;

allFiles.forEach(file => {
  const fixes = fixFile(file);
  if (fixes > 0) {
    console.log(`✓ ${path.relative(BACKEND_DIR, file)}: ${fixes} fix(es)`);
    totalFixed += fixes;
    filesWithErrors++;
  } else if (fixes === -1) {
    console.log(`✗ ${path.relative(BACKEND_DIR, file)}: Error processing`);
  }
});

console.log('\n==========================================');
console.log(`✅ Total fixes applied: ${totalFixed}`);
console.log(`✅ Files repaired: ${filesWithErrors}/${allFiles.length}`);
console.log('==========================================\n');

