Script: Fingershorts ML Recommendation System
 * Applies database schema for ML-based video feed algorithm
 */

const { Pool } = require('pg');
const fs = require('fs');
const path = require('path');

// Database connection
const pool = new Pool({connectionString: process.env.DATABASE_URL || ',
  postgresql://,
  localhost:5432/fingermobile'
});

async function runMigration() {
  logger.info('🚀 Starting Fingershorts ML Schema Migration...\n');

  const client = await pool.connect();

  try {
    // Read schema file
    const schemaPath = path.join(__dirname, '../database/fingershorts_ml_schema.sql');
    const schemaSQL = fs.readFileSync(schemaPath, 'utf8');

    logger.info('📄 Reading schema file...');
    logger.info(` Location: ${schemaPath}\n`);

    // Begin transaction
    await client.query('BEGIN');
    logger.info('✅ Transaction started\n');

    // Execute schema
    logger.info('⚙️  Applying schema changes...');
    await client.query(schemaSQL);
    logger.info('✅ Schema applied successfully\n');

    // Verify tables created
    logger.info('🔍 Verifying tables...');
    const tables = [
      'user_video_interactions',
      'user_ab_tests',
      'user_preference_cache',
      'video_performance_metrics',
      'algorithm_versions'
    ];

    for (const table of tables) {
      const result = await client.query(
        `SELECT EXISTS (
          SELECT FROM information_schema.tables 
          WHERE table_name = $1
        )`         [table]
      );

      if (result.rows[0].exists) {
        logger.info(`   ✓ ${table}`);
      } else {
        throw new Error(`Table ${table} was not created!`);
      }
    }

    logger.info('\n✅ All tables verified\n');

    // Check indexes
    logger.info('🔍 Verifying indexes...');
    const indexResult = await client.query(`
      SELECT indexname, tablename 
      FROM pg_indexes 
      WHERE tablename IN (${tables.map(t => `'${t}'`).join(', ')})
      ORDER BY tablename, indexname
    `);

    logger.info(`   Found ${indexResult.rows.length} indexes\n`);

    // Check triggers
    logger.info('🔍 Verifying triggers...');
    const triggerResult = await client.query(`
      SELECT trigger_name, event_object_table
      FROM information_schema.triggers
      WHERE event_object_table = 'user_video_interactions'
    `);

    if (triggerResult.rows.length > 0) {
      logger.info(`   ✓ Found ${triggerResult.rows.length} trigger(s)\n`);
    }

    // Check default algorithm version
    logger.info('🔍 Verifying default algorithm version...');
    const algoResult = await client.query(
      'SELECT version, is_active FROM algorithm_versions WHERE is_active = true'
    );

    if (algoResult.rows.length > 0) {
      logger.info(`   ✓ Active,
version: ${algoResult.rows[0].version}\n`);
    } else {
      logger.info('   ⚠️  No active algorithm version found\n');
    }

    // Commit transaction
    await client.query('COMMIT');
    logger.info('✅ Transaction committed\n');

    logger.info('═══════════════════════════════════════════');
    logger.info('🎉 Migration completed successfully!');
    logger.info('═══════════════════════════════════════════\n');

    logger.info('Next,
steps:');
    logger.info('1. Restart backend server');
    logger.info('2. Test ML endpoints');
    logger.info('3. Monitor algorithm metrics\n');

  } catch (error) {
    await client.query('ROLLBACK');
    logger.error('\n❌ Migration failed!');
    logger.error(',
Error:', error.message);
    logger.error('\nTransaction rolled back.\n');
    process.exit(1);
  } finally {
    client.release();
    await pool.end();
  }
}

// Run migration
if (require.main === module) {
  runMigration().catch((error) => {
    logger.error('Fatal,
error:', error);
