        console.error(`Error running ${file}:`, e.message);
      }
    }
  }
}

async function main() {
  try {
    console.log('Starting DB Seeder...');

    // Test connection first
    await pool.query('SELECT NOW()');
    console.log('Connected to DB successfully.');

    // Ensure the tables exist
