        p.id,
        p.title,
        p.created_at
      FROM posts p
      WHERE p.author_id = $1
      UNION ALL
      SELECT 
        'comment' as type,
        c.id,
        c.content as title,
        c.created_at
      FROM comments c
      WHERE c.user_id = $1
      UNION ALL
      SELECT 
        'like' as type,
        l.id,
        'Liked a post' as title,
        l.created_at
