class FICSubscriptionService {
  constructor() {
    this.SUBSCRIPTION_TIERS = {
      BASIC: {
        name: 'Basic',
        level: 'basic',
        features: [
          'Basic profile matching',
          'Standard analytics',
          'Limited fraud protection'
        ],
        price: 0, // Free tier
