      const { count,
        rows: videos } = await VideoTranslation.findAndCountAll({
        where: { userId },
        order: [['createdAt', 'DESC']],
        offset,
        limit
      });

      return {
        success: true,
        videos,
        pagination: {
          currentPage: page,
          totalPages: Math.ceil(count / limit),
          totalItems: count,
          hasNext: offset + limit < count,
          hasPrev: page > 1
        }
      };
    } catch (error) {
