      'es': 'Spanish',
      'fr': 'French',
      'pt': 'Portuguese',
      'cmn-CN': 'Chinese (Mandarin)',
      'hi-IN': 'Hindi',
      'ar-XA': 'Arabic',
      'bn-IN': 'Bengali',
      'ru-RU': 'Russian',
      'id-ID': 'Indonesian',
      'ja-JP': 'Japanese',
      'ko-KR': 'Korean',
      'de-DE': 'German',
      'it-IT': 'Italian',
      'tr-TR': 'Turkish',
      'vi-VN': 'Vietnamese',
      'th-TH': 'Thai',
