        } else {
          await client.query(
            `UPDATE video_processing_jobs 
             SET progress = $1
             WHERE id = $2`,
            [Math.min(progress, 100), jobId],
          );
        }
      }, 1000);

      // Handle FFmpeg process completion
      ffmpegProcess.on('close', (code) => {
        if (code !== 0) {
          this.completeJobWithError(
            client,
            jobId,
            `FFmpeg filter exited with code ${code}`,
