        await client.query('COMMIT');

        // Log security event
        await logSecurityEvent(memberId, 'FIAT_WITHDRAWAL', {
          memberId,
          amount,
          gateway: gatewayName
        });

        return {
          success: true,
          message: 'Withdrawal request submitted',
          new_balance: walletInfo.fiat_wallet.balance - amount
        };
      } finally {
        client.release();
      }
    } catch (error) {
      logger.error('Error withdrawing fiat:', error);
      throw error;
    }
  }
}

