      }

      if (options.tag) {
        query += ` AND $${params.length + 1} = ANY(tags)`;
        params.push(options.tag);
      }

      query += ' ORDER BY created_at DESC';

      if (options.limit) {
        query += ` LIMIT $${params.length + 1}`;
        params.push(options.limit);
      }

      const result = await identityDb.query(query, params);

