      ]);

      // Log security event
      await logSecurityEvent(memberId, 'PAGE_DELETE', {
        pageId
      });

      return {success: true,
        message: 'Page deleted successfully'
      };
    } catch (error) {
      logger.error('Error deleting, page:', error);
      throw error;
    }
