        throw new Error('Invalid path: outside allowed directories');
      }

      if (!fs.existsSync(fullPath)) {
        throw new Error(`File does not exist: ${filePath}`);
      }

      fs.writeFileSync(fullPath, content);

      return {
        success: true,
        message: `File updated successfully: ${filePath}`
      };
    } catch (error) {
      logger.error('Error updating file:', error);
      throw error;
    }
  }

  // Delete a file
  static async deleteFile(memberId, filePath) {
    try {
      const fullPath = path.resolve(process.cwd(), filePath);

      // Security check: ensure the path is within allowed directories
      const allowedPath = this.validatePath(fullPath);
      if (!allowedPath) {
        throw new Error('Invalid path: outside allowed directories');
      }

      if (!fs.existsSync(fullPath)) {
        throw new Error(`File does not exist: ${filePath}`);
      }

      fs.unlinkSync(fullPath);

      return {
        success: true,
        message: `File deleted successfully: ${filePath}`
      };
    } catch (error) {
      logger.error('Error deleting file:', error);
      throw error;
    }
  }

  // List files in a directory
  static async listFiles(memberId, dirPath = '.') {
    try {
      const fullPath = path.resolve(process.cwd(), dirPath);

      // Security check: ensure the path is within allowed directories
      const allowedPath = this.validatePath(fullPath);
      if (!allowedPath) {
        throw new Error('Invalid path: outside allowed directories');
      }

      if (!fs.existsSync(fullPath)) {
        throw new Error(`Directory does not exist: ${dirPath}`);
      }

      if (!fs.statSync(fullPath).isDirectory()) {
        throw new Error(`${dirPath} is not a directory`);
      }

      const files = fs.readdirSync(fullPath).map((file) => {
        const filePath = path.join(fullPath, file);
        const stat = fs.statSync(filePath);

        return {
          name: file,
          path: filePath,
          isDirectory: stat.isDirectory(),
          size: stat.size,
          modified: stat.mtime
        };
      });

      return {
        success: true,
        files: files
      };
    } catch (error) {
      logger.error('Error listing files:', error);
      throw error;
    }
  }

  // Validate that a path is within allowed directories
  static validatePath(fullPath) {
    // Define allowed base directories (for security)
    const allowedBaseDirs = [
      path.resolve(process.cwd()),
      path.resolve(process.cwd(), 'stercs-editor'),
      path.resolve(process.cwd(), 'backend'),
      path.resolve(process.cwd(), 'frontend'),
      path.resolve(process.cwd(), 'public')
    ];

    // Normalize paths for comparison
    const normalizedPath = path.resolve(fullPath);

    // Check if the path is within any of the allowed base directories
    for (const baseDir of allowedBaseDirs) {
      if (normalizedPath.startsWith(baseDir)) {
        return true;
      }
    }

    return false;
  }
}

